(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-044"]={"sura":44,"name_ar":"الدخان","name_en":"Ad-Dukhan","verses":59,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":59,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=8\" class=\"link\">44:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\nமுஸ்னத் அல்-பஸ்ஸாரில், அபூ அத்-துஃபைல் ஆமிர் பின் வாஸிலா (ரழி) அவர்கள், ஜைத் பின் ஹாரிஸா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இப்னு ஸய்யாதிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">خَبَأْتُ</span> <span class=\"quran-arabic-font text-success\">خَبْأً</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ؟</span>»<br />\r\n<br />\r\n(நான் உன்னிடமிருந்து ஒன்றை மறைத்து வைத்திருக்கிறேன், அது என்ன?) அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸூரத்துத் துகானை அவனிடமிருந்து (மனதிற்குள்) மறைத்து வைத்திருந்தார்கள். அதற்கு அவன் (இப்னு ஸய்யாத்), \"அது 'அத்-துக்' (புகை)\" என்று கூறினான். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اخْسَأْ</span> <span class=\"quran-arabic-font text-success\">فَلَنْ</span> <span class=\"quran-arabic-font text-success\">تَعْدُوَ</span> <span class=\"quran-arabic-font text-success\">قَدْرَكَ</span>»<br />\r\n<br />\r\n(அப்பால் போ! உன் தகுதியை மீறி (எதையும் அறிந்து கொள்ள) முடியாது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حم</span> * <span class=\"quran-arabic-font text-success\">وَالْكِتَابِ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينِ</span><br />\r\n<br />\r\n(ஹா, மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக!)<br />\r\n<br />\r\n<strong>குர்ஆன் லைலத்துல் கத்ரில் அருளப்பட்டது</strong><br />\r\n<br />\r\nமகத்துவமிக்க குர்ஆனை பாக்கியம் நிறைந்த இரவான 'லைலத்துல் கத்ர்' (விதி நிர்ணயிக்கப்படும் இரவு) அன்று தான் அருளியதாக அல்லாஹ் நமக்குக் கூறுகிறான். இதனை அவன் மற்றோர் இடத்திலும் குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَـهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">لَيْلَةِ</span> <span class=\"quran-arabic-font text-success\">الْقَدْرِ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் இதனை ‘கத்ரு’ எனும் கண்ணியமிக்க இரவில் இறக்கினோம்.) (<a href=\"qurandisp.php?sura=97&ayah=1\" class=\"link\">97:1</a>). இது ரமளான் மாதத்தில் நிகழ்ந்தது; இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">شَهْرُ</span> <span class=\"quran-arabic-font text-success\">رَمَضَانَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنُ</span><br />\r\n<br />\r\n(ரமளான் மாதம் எத்தகையது என்றால், அதில் தான் குர்ஆன் அருளப்பட்டது.) (<a href=\"qurandisp.php?sura=2&ayah=185\" class=\"link\">2:185</a>). இது தொடர்பான ஹதீஸ்களை நாம் ஏற்கனவே ஸூரத்துல் பகராவின் தஃப்ஸீரில் குறிப்பிட்டுள்ளோம், எனவே அவற்றை மீண்டும் இங்கு கூற வேண்டிய அவசியமில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُنذِرِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் எச்சரிக்கை செய்து கொண்டே இருக்கிறோம்.) இதன் பொருள், அல்லாஹ்வின் அடியார்களுக்கு எதிராக அவனது சான்று நிலைநாட்டப்படுவதற்காக, ஷரீஅத்தின் அடிப்படையில் அவர்களுக்கு எது நன்மை பயக்கும் மற்றும் எது தீங்கு விளைவிக்கும் என்பதை அவர்களுக்குத் தெரிவிப்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">يُفْرَقُ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">أَمْرٍ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٍ</span><br />\r\n<br />\r\n(அதில் (அந்த இரவில்) உறுதியான ஒவ்வொரு காரியமும் தீர்மானிக்கப்படுகிறது.) இதன் பொருள்: லைலத்துல் கத்ர் இரவில், ‘அல்-லவ்ஹுல் மஹ்ஃபூழ்’ (பாதுகாக்கப்பட்ட பலகை) இலிருந்து விதிகள் வானவ எழுத்தாளர்களுக்கு மாற்றப்படுகின்றன. அவர்கள் வரவிருக்கும் ஆண்டிற்கான ஆயுட்காலம், வாழ்வாதாரம் மற்றும் அந்த ஆண்டு முடியும் வரை என்னென்ன நிகழும் என்பது போன்ற விபரங்களை எழுதுகிறார்கள். இது இப்னு உமர் (ரழி), முஜாஹித் (ரழி), அபூ மாலிக் (ரழி), அத்-தஹ்ஹாக் (ரழி) மற்றும் முன்னோர்களான ஸலஃபாக்களிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n(ஹகீம்) என்பதன் பொருள் தீர்மானிக்கப்பட்டது அல்லது உறுதி செய்யப்பட்டது என்பதாகும், அதனை எவராலும் மாற்றவோ அல்லது திருத்தவோ முடியாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْراً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِنْدِنَآ</span><br />\r\n<br />\r\n(நம்மிடமிருந்து ஒரு கட்டளையாக.) இதன் பொருள், நிகழக்கூடிய மற்றும் அல்லாஹ்வால் தீர்மானிக்கப்பட்ட அனைத்தும், மற்றும் அவன் இறக்கிய வஹீ (இறைச்செய்தி) ஆகிய அனைத்தும் அவனது கட்டளைப்படியும், அவனது அனுமதியுடனும், அவனது ஞானப்படியுமே நிகழ்கின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُرْسِلِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் (தூதர்களை) அனுப்பிக்கொண்டே இருக்கிறோம்,) இதன் பொருள், மனிதர்களுக்கு அல்லாஹ்வின் தெளிவான அத்தாட்சிகளை ஓதிக் காட்டுவதற்காகத் தூதர்களை அனுப்புவதைக் குறிக்கிறது. இதன் தேவை மிகவும் அவசியமானதாக இருந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَحْمَةً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span><br />\r\n<br />\r\n((இது) உமது இறைவனிடமிருந்து ஒரு கருணையாகும். நிச்சயமாக அவன் யாவற்றையும் செவியேற்பவன், நன்கறிந்தவன். அவன் வானங்கள், பூமி மற்றும் அவற்றுக்கு இடையில் உள்ளவை அனைத்திற்கும் இறைவன் ஆவான்.) இதன் பொருள், இந்தக் குர்ஆனை அருளியவன் வானங்கள், பூமி மற்றும் அவற்றுக்கிடையே உள்ள அனைத்தின் இறைவனும், படைப்பாளனும், அதிபதியும் ஆவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">مُّوقِنِينَ</span><br />\r\n<br />\r\n(நீங்கள் உறுதியான நம்பிக்கை கொண்டவர்களாக இருந்தால்.) பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">يُحْىِ</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِكُمُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span><br />\r\n<br />\r\n(வணக்கத்திற்குரியவன் அவனைத் தவிர வேறு யாருமில்லை; அவனே உயிர்ப்பிக்கிறான், அவனே மரணிக்கச் செய்கிறான். அவனே உங்கள் இறைவனும், உங்கள் முன்னோர்களின் இறைவனும் ஆவான்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">يُحْىِ</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ</span><br />\r\n<br />\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன். வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்குரியதே; வணக்கத்திற்குரியவன் அவனைத் தவிர வேறு யாருமில்லை. அவனே உயிர்ப்பிக்கிறான், அவனே மரணிக்கச் செய்கிறான்...\") (<a href=\"qurandisp.php?sura=7&ayah=158\" class=\"link\">7:158</a>).<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nமுஸ்னத் அல்-பஸ்ஸாரில், அபூ அத்-துஃபைல் ஆமிர் பின் வாஸிலா (ரழி) அவர்கள், ஜைத் பின் ஹாரிஸா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இப்னு ஸய்யாதிடம் கூறினார்கள்:\n\r\n\n\r\n«إِنِّي قَدْ خَبَأْتُ خَبْأً فَمَا هُوَ؟»\n\r\n\n\r\n(நான் உன்னிடமிருந்து ஒன்றை மறைத்து வைத்திருக்கிறேன், அது என்ன?) அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸூரத்துத் துகானை அவனிடமிருந்து (மனதிற்குள்) மறைத்து வைத்திருந்தார்கள். அதற்கு அவன் (இப்னு ஸய்யாத்), \"அது 'அத்-துக்' (புகை)\" என்று கூறினான். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اخْسَأْ فَلَنْ تَعْدُوَ قَدْرَكَ»\n\r\n\n\r\n(அப்பால் போ! உன் தகுதியை மீறி (எதையும் அறிந்து கொள்ள) முடியாது.)\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nحم * وَالْكِتَابِ الْمُبِينِ\n\r\n\n\r\n(ஹா, மீம். தெளிவான இவ்வேதத்தின் மீது சத்தியமாக!)\n\r\n\n\r\nகுர்ஆன் லைலத்துல் கத்ரில் அருளப்பட்டது\n\r\n\n\r\nமகத்துவமிக்க குர்ஆனை பாக்கியம் நிறைந்த இரவான 'லைலத்துல் கத்ர்' (விதி நிர்ணயிக்கப்படும் இரவு) அன்று தான் அருளியதாக அல்லாஹ் நமக்குக் கூறுகிறான். இதனை அவன் மற்றோர் இடத்திலும் குறிப்பிடுகிறான்:\n\r\n\n\r\nإِنَّا أَنزَلْنَـهُ فِى لَيْلَةِ الْقَدْرِ\n\r\n\n\r\n(நிச்சயமாக நாம் இதனை ‘கத்ரு’ எனும் கண்ணியமிக்க இரவில் இறக்கினோம்.) (97:1). இது ரமளான் மாதத்தில் நிகழ்ந்தது; இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nشَهْرُ رَمَضَانَ الَّذِى أُنزِلَ فِيهِ الْقُرْآنُ\n\r\n\n\r\n(ரமளான் மாதம் எத்தகையது என்றால், அதில் தான் குர்ஆன் அருளப்பட்டது.) (2:185). இது தொடர்பான ஹதீஸ்களை நாம் ஏற்கனவே ஸூரத்துல் பகராவின் தஃப்ஸீரில் குறிப்பிட்டுள்ளோம், எனவே அவற்றை மீண்டும் இங்கு கூற வேண்டிய அவசியமில்லை.\n\r\n\n\r\nإِنَّا كُنَّا مُنذِرِينَ\n\r\n\n\r\n(நிச்சயமாக நாம் எச்சரிக்கை செய்து கொண்டே இருக்கிறோம்.) இதன் பொருள், அல்லாஹ்வின் அடியார்களுக்கு எதிராக அவனது சான்று நிலைநாட்டப்படுவதற்காக, ஷரீஅத்தின் அடிப்படையில் அவர்களுக்கு எது நன்மை பயக்கும் மற்றும் எது தீங்கு விளைவிக்கும் என்பதை அவர்களுக்குத் தெரிவிப்பதாகும்.\n\r\n\n\r\nفِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ\n\r\n\n\r\n(அதில் (அந்த இரவில்) உறுதியான ஒவ்வொரு காரியமும் தீர்மானிக்கப்படுகிறது.) இதன் பொருள்: லைலத்துல் கத்ர் இரவில், ‘அல்-லவ்ஹுல் மஹ்ஃபூழ்’ (பாதுகாக்கப்பட்ட பலகை) இலிருந்து விதிகள் வானவ எழுத்தாளர்களுக்கு மாற்றப்படுகின்றன. அவர்கள் வரவிருக்கும் ஆண்டிற்கான ஆயுட்காலம், வாழ்வாதாரம் மற்றும் அந்த ஆண்டு முடியும் வரை என்னென்ன நிகழும் என்பது போன்ற விபரங்களை எழுதுகிறார்கள். இது இப்னு உமர் (ரழி), முஜாஹித் (ரழி), அபூ மாலிக் (ரழி), அத்-தஹ்ஹாக் (ரழி) மற்றும் முன்னோர்களான ஸலஃபாக்களிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது.\n\r\n\n\r\nحَكِيمٌ\n\r\n\n\r\n(ஹகீம்) என்பதன் பொருள் தீர்மானிக்கப்பட்டது அல்லது உறுதி செய்யப்பட்டது என்பதாகும், அதனை எவராலும் மாற்றவோ அல்லது திருத்தவோ முடியாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَمْراً مِّنْ عِنْدِنَآ\n\r\n\n\r\n(நம்மிடமிருந்து ஒரு கட்டளையாக.) இதன் பொருள், நிகழக்கூடிய மற்றும் அல்லாஹ்வால் தீர்மானிக்கப்பட்ட அனைத்தும், மற்றும் அவன் இறக்கிய வஹீ (இறைச்செய்தி) ஆகிய அனைத்தும் அவனது கட்டளைப்படியும், அவனது அனுமதியுடனும், அவனது ஞானப்படியுமே நிகழ்கின்றன.\n\r\n\n\r\nإِنَّا كُنَّا مُرْسِلِينَ\n\r\n\n\r\n(நிச்சயமாக நாம் (தூதர்களை) அனுப்பிக்கொண்டே இருக்கிறோம்,) இதன் பொருள், மனிதர்களுக்கு அல்லாஹ்வின் தெளிவான அத்தாட்சிகளை ஓதிக் காட்டுவதற்காகத் தூதர்களை அனுப்புவதைக் குறிக்கிறது. இதன் தேவை மிகவும் அவசியமானதாக இருந்தது.\n\r\n\n\r\nرَحْمَةً مِّن رَّبِّكَ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ رَبِّ السَّمَـوَتِ وَالاٌّرْضِ وَمَا بَيْنَهُمَا\n\r\n\n\r\n((இது) உமது இறைவனிடமிருந்து ஒரு கருணையாகும். நிச்சயமாக அவன் யாவற்றையும் செவியேற்பவன், நன்கறிந்தவன். அவன் வானங்கள், பூமி மற்றும் அவற்றுக்கு இடையில் உள்ளவை அனைத்திற்கும் இறைவன் ஆவான்.) இதன் பொருள், இந்தக் குர்ஆனை அருளியவன் வானங்கள், பூமி மற்றும் அவற்றுக்கிடையே உள்ள அனைத்தின் இறைவனும், படைப்பாளனும், அதிபதியும் ஆவான்.\n\r\n\n\r\nإِن كُنتُمْ مُّوقِنِينَ\n\r\n\n\r\n(நீங்கள் உறுதியான நம்பிக்கை கொண்டவர்களாக இருந்தால்.) பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَ إِلَـهَ إِلاَّ هُوَ يُحْىِ وَيُمِيتُ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ الاٌّوَّلِينَ\n\r\n\n\r\n(வணக்கத்திற்குரியவன் அவனைத் தவிர வேறு யாருமில்லை; அவனே உயிர்ப்பிக்கிறான், அவனே மரணிக்கச் செய்கிறான். அவனே உங்கள் இறைவனும், உங்கள் முன்னோர்களின் இறைவனும் ஆவான்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nقُلْ يَأَيُّهَا النَّاسُ إِنِّى رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا الَّذِى لَهُ مُلْكُ السَّمَـوَتِ وَالاٌّرْضِ لا إِلَـهَ إِلاَّ هُوَ يُحْىِ وَيُمِيتُ\n\r\n\n\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன். வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்குரியதே; வணக்கத்திற்குரியவன் அவனைத் தவிர வேறு யாருமில்லை. அவனே உயிர்ப்பிக்கிறான், அவனே மரணிக்கச் செய்கிறான்...\") (7:158)."},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=16\" class=\"link\">44:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>வானம் தெளிவான புகையைக் கொண்டுவரும் நாளைப் பற்றி இணைவைப்பாளர்களுக்கு எச்சரிக்கை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: இந்த இணைவைப்பாளர்கள் (சத்தியத்தின் மீது) சந்தேகம் கொண்டு விளையாடிக்கொண்டிருக்கிறார்கள். அதாவது, அவர்களிடம் உறுதியான உண்மை வந்துவிட்டது, ஆனால் அவர்கள் அதைச் சந்தேகிப்பதோடு நம்பவும் மறுக்கிறார்கள். பிறகு அல்லாஹ் அவர்களை எச்சரித்தும் அச்சுறுத்தியும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْتَقِبْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بِدُخَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக.) மஸ்ரூக் (ரஹ்) அவர்கள் கூறியதாவது: \"நாங்கள் கூஃபாவிலுள்ள கிந்தா வாசலுக்கு அருகிலுள்ள ஒரு மஸ்ஜிதிற்குள் நுழைந்தோம். அங்கே ஒரு மனிதர் தம் தோழர்களுக்கு பின்வரும் வசனத்தை ஓதிக்கொண்டிருந்தார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بِدُخَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாள்.) 'அது என்னவென்று உங்களுக்குத் தெரியுமா?' என்று அவர் அவர்களிடம் கேட்டுவிட்டு, 'அது மறுமை நாளில் வரக்கூடிய புகையாகும். அது நயவஞ்சகர்களின் செவிப்புலனையும் பார்வையையும் பறித்துவிடும். ஆனால் நம்பிக்கையாளர்களுக்கு (முஃமின்களுக்கு) அது ஒரு ஜலதோஷம் (சளி) பிடித்ததைப் போன்ற உணர்வைத்தான் ஏற்படுத்தும்' என்றார்.\" மஸ்ரூக் (ரஹ்) மேலும் கூறினார்கள்: \"நாங்கள் இப்னு மஸ்ஊத் (ரழி) அவர்களிடம் வந்து அந்த மனிதர் சொன்னதைப் பற்றிக் கூறினோம். அப்போது அவர்கள் படுத்துக்கொண்டிருந்தார்கள்; இதைக் கேட்டதும் திடுக்கிட்டு எழுந்து அமர்ந்து கூறினார்கள்: 'அல்லாஹ் உங்கள் நபியிடம் (ஸல்) கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَسْـَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنَآ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَلِّفِينَ</span><br />\r\n<br />\r\n(நபியே!) நீர் கூறுவீராக: இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை; மேலும் நான் போலியாகப் பேசுபவனும் (நடிப்பவனும்) அல்ல.' (<a href=\"qurandisp.php?sura=38&ayah=86\" class=\"link\">38:86</a>). ஒரு மனிதருக்குத் தெரியாத ஒரு விஷயத்தைப் பற்றி, 'அல்லாஹ்வே நன்கறிந்தவன்' என்று கூறுவதும் அறிவின் ஒரு பகுதியாகும். இது சம்பந்தமாக ஒரு ஹதீஸை நான் உங்களுக்குக் கூறுகிறேன். குரைஷிகள் இஸ்லாத்தை ஏற்க மறுத்து பிடிவாதம் காட்டியபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராக, யூசுஃப் (அலை) அவர்களின் காலத்தில் ஏற்பட்ட பஞ்சத்தைப் போன்ற ஒரு பஞ்சம் அவர்கள் மீது ஏற்பட வேண்டும் என்று அல்லாஹ்விடம் பிரார்த்தித்தார்கள். அதன் விளைவாக அவர்கள் கடும் பசியால் வாடி, எலும்புகளையும் செத்த பிராணிகளையும் உண்ணும் நிலைக்குத் தள்ளப்பட்டார்கள். அவர்கள் வானத்தைப் பார்த்தபோது கடும் பசியினால் அவர்களுக்குப் புகையைப் போலத்தான் தெரிந்தது.\" மற்றொரு அறிவிப்பில்: \"ஒரு மனிதன் தன் பசியின் சோர்வினால் வானத்தைப் பார்க்கும்போது, அவருக்கும் வானத்திற்கும் இடையில் ஒரு புகைமூட்டம் இருப்பதைப் போன்றே காண்பார்\" என்றுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْتَقِبْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بِدُخَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> - <span class=\"quran-arabic-font text-success\">يَغْشَى</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span><br />\r\n<br />\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக. அது மக்களைச் சூழ்ந்துகொள்ளும்; இது ஒரு நோவினை தரும் வேதனையாகும்.) ஒரு மனிதர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, \"அல்லாஹ்வின் தூதரே! முதர் கோத்திரத்தாருக்காக மழை பொழிய அல்லாஹ்விடம் பிரார்த்தியுங்கள், ஏனெனில் அவர்கள் (பஞ்சத்தால்) இறந்துகொண்டிருக்கிறார்கள்\" என்று வேண்டினார். ஆகவே நபி (ஸல்) அவர்கள் அவர்களுக்காக மழை வேண்டினார்கள், மழையும் பொழிந்தது. பின்னர் இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كَاشِفُواْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَآئِدُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் இந்த வேதனையைச் சிறிது காலத்திற்கு நீக்குவோம். எனினும் நிச்சயமாக நீங்கள் (மீண்டும் பழைய நிலைக்கே) திரும்புவீர்கள்.) இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"மறுமை நாளில் வேதனை நீக்கப்படும் என்று நீங்கள் கருதுகிறீர்களா? அவர்களுக்கு இவ்வுலகில் வேதனை நீக்கப்பட்டு வசதி அளிக்கப்பட்டபோது, அவர்கள் மீண்டும் தங்கள் பழைய நிராகரிப்பு நிலைக்கே திரும்பிவிட்டார்கள்.\" அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">نَبْطِشُ</span> <span class=\"quran-arabic-font text-success\">الْبَطْشَةَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُنتَقِمُونَ</span><br />\r\n<br />\r\n(நாம் பெரும் பிடியாகப் பிடிக்கும் நாளில், நிச்சயமாக நாம் பழிவாங்குவோம்.) இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"இது பத்ர் நாளைக் குறிக்கிறது.\" மேலும் அவர்கள் கூறினார்கள்: \"ஐந்து விஷயங்கள் நிகழ்ந்துவிட்டன: புகை (துக்கான்), ரோமர்களின் வெற்றி, சந்திரன் பிளந்தது, பெரும் பிடி (பத்ஷா), மற்றும் வேதனை.\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது. மேலும் இமாம் அஹ்மத், திர்மிதி, நஸாயீ, இப்னு ஜரீர் மற்றும் இப்னு அபீ ஹாதிம் ஆகியோரும் பல அறிவிப்பாளர் தொடர்களின் வழியாக இதனைப் பதிவு செய்துள்ளனர். முஜாஹித், அபுல் ஆலியா, இப்ராஹீம் அந்நகஈ, அத்-தஹ்ஹாக் மற்றும் அதிய்யா அல்-அவ்ஃபீ போன்ற பல ஸலஃபுகள், 'புகை' என்பது ஏற்கனவே நிகழ்ந்துவிட்டது என்ற இப்னு மஸ்ஊத் (ரழி) அவர்களின் கருத்தையே ஏற்றுக்கொண்டனர். இப்னு ஜரீர் என்பவரும் இக்கருத்தையே கொண்டுள்ளார்.<br />\r\n<br />\r\nஅபூ ஸரீஹா ஹுதைஃபா பின் அஸீத் அல்-கிஃபாரி (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில் கூறப்பட்டுள்ளதாவது: \"நாங்கள் மறுமை நாளைப் பற்றி விவாதித்துக் கொண்டிருந்தபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓர் அறையிலிருந்து எங்களை நோக்கி வந்து கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَرَوْا</span> <span class=\"quran-arabic-font text-success\">عَشْرَ</span> <span class=\"quran-arabic-font text-success\">آيَاتٍ</span>: <span class=\"quran-arabic-font text-success\">طُلُوعَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَغْرِبِهَا،</span> <span class=\"quran-arabic-font text-success\">وَالدُّخَانَ،</span> <span class=\"quran-arabic-font text-success\">وَالدَّابَّةَ،</span> <span class=\"quran-arabic-font text-success\">وَخُرُوجَ</span> <span class=\"quran-arabic-font text-success\">يَأْجُوجَ</span> <span class=\"quran-arabic-font text-success\">وَمَأْجُوجَ،</span> <span class=\"quran-arabic-font text-success\">وَنُزُولَ</span> <span class=\"quran-arabic-font text-success\">عِيْسَى</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">وَالدَّجَّالَ،</span> <span class=\"quran-arabic-font text-success\">وَثَلَاثَةَ</span> <span class=\"quran-arabic-font text-success\">خُسُوفٍ</span>: <span class=\"quran-arabic-font text-success\">خَسْفٌ</span> <span class=\"quran-arabic-font text-success\">بِالْمَشْرِقِ،</span> <span class=\"quran-arabic-font text-success\">وَخَسْفٌ</span> <span class=\"quran-arabic-font text-success\">بِالْمَغْرِبِ،</span> <span class=\"quran-arabic-font text-success\">وَخَسْفٌ</span> <span class=\"quran-arabic-font text-success\">بِجَزِيرَةِ</span> <span class=\"quran-arabic-font text-success\">الْعَرَبِ،</span> <span class=\"quran-arabic-font text-success\">وَنَارًا</span> <span class=\"quran-arabic-font text-success\">تَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">قَعْرِ</span> <span class=\"quran-arabic-font text-success\">عَدَنَ</span> <span class=\"quran-arabic-font text-success\">تَسُوقُ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَحْشُرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">تَبِيتُ</span> <span class=\"quran-arabic-font text-success\">مَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">بَاتُوا،</span> <span class=\"quran-arabic-font text-success\">وَتَقِيلُ</span> <span class=\"quran-arabic-font text-success\">مَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>»<br />\r\n<br />\r\n(பத்து அடையாளங்களை நீங்கள் காணும் வரை மறுமை நாள் வராது. அவை: சூரியன் மேற்கிலிருந்து உதிப்பது; புகை; (தாப்பத்துல் அர்ள் எனும்) பிராணி; யஃஜூஜ் மற்றும் மஃஜூஜ் ஆகியோரின் வருகை; ஈஸா இப்னு மர்யம் (அலை) அவர்களின் வருகை; தஜ்ஜால்; மூன்று நிலச்சரிவுகள் (பூமி உள்வாங்குதல்) - ஒன்று கிழக்கிலும், ஒன்று மேற்கிலும், மற்றொன்று அரேபிய தீபகற்பத்திலும் ஏற்படும்; இறுதியாக ஏடன் (Aden) பகுதியின் ஆழத்திலிருந்து ஒரு நெருப்பு புறப்பட்டு மக்களை விரட்டிச் செல்லும் - அல்லது மக்களை ஒன்றுதிரட்டும் - அவர்கள் இரவில் தங்கும் இடத்தில் அதுவும் தங்கும், அவர்கள் பகலில் ஓய்வெடுக்கும் இடத்தில் அதுவும் தங்கும்.)\" இதனை இமாம் முஸ்லிம் மட்டும் தமது ஸஹீஹில் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\nபுகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவாகியுள்ள மற்றுமொரு செய்தியில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இப்னு ஸய்யாதிடம்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">خَبَأْتُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">خَبْأ</span>»<br />\r\n<br />\r\n(நான் உனக்காக ஒரு விஷயத்தை மனதிற்குள் மறைத்து வைத்துள்ளேன், அது என்னவென்று சொல்?) என்றார்கள். அதற்கு அவன், 'அது அத்-துக்' (அதாவது புகை) என்றான். நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اخْسَأْ</span> <span class=\"quran-arabic-font text-success\">فَلَنْ</span> <span class=\"quran-arabic-font text-success\">تَعْدُوَ</span> <span class=\"quran-arabic-font text-success\">قَدْرَك</span>»<br />\r\n<br />\r\n(இழிவடைந்து போ! உனது தகுதியை உன்னால் தாண்ட முடியாது) என்றார்கள். இப்னு மஸ்ஊத் (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْتَقِبْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بِدُخَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக) என்ற வசனத்தைத் தான் அவனிடம் மறைத்து வைத்திருந்தார்கள்.\" புகை என்பது இன்னும் ஏற்படவில்லை என்பதையே இது காட்டுகிறது. இப்னு ஸய்யாத் என்பவன் ஒரு ஜோதிடனாவான்; அவன் ஜின்கள் மூலம் செய்திகளைக் கேட்பான். ஜின்களின் பேச்சு தெளிவாக இருக்காது என்பதால் அவன் 'அத்-துக்கான்' என்று முழுமையாகச் சொல்லாமல் 'அத்-துக்' என்று கூறினான். அவன் தகவல்களைப் பெறுவது ஷைத்தான்கள் மூலமாகத்தான் என்பதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உறுதி செய்தபோதுதான், \"இழிவடைந்து போ! உனது தகுதியை உன்னால் தாண்ட முடியாது\" என்று கூறினார்கள்.<br />\r\n<br />\r\nபுகை என்பது இனிமேல் வரப்போகும் மறுமை நாளின் அடையாளங்களில் ஒன்று என்பதை உறுதிப்படுத்தும் ஏராளமான ஸஹீஹ் மற்றும் ஹஸன் தரத்திலான மர்ஃபூஃ (நபியவர்கள் கூறியவை) மற்றும் மவ்கூஃப் (ஸஹாபாக்கள் கூறியவை) ஹதீஸ்கள் உள்ளன. குர்ஆன் வசனங்களின் வெளிப்படையான பொருளும் இதுவேயாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْتَقِبْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَأْتِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">بِدُخَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக.) அதாவது, அது மக்கள் அனைவருக்கும் தெளிவாகத் தெரியும் வகையில் இருக்கும். இப்னு மஸ்ஊத் (ரழி) அவர்களின் விளக்கப்படி, அது அவர்களின் கடுமையான பசியினால் ஏற்பட்ட ஒரு பிரமையாகும். மேலும் அல்லாஹ்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَغْشَى</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span><br />\r\n<br />\r\n(அது மக்களைச் சூழ்ந்துகொள்ளும்) என்று கூறுகிறான். அதாவது, அது அனைவரையும் மூடி ஆட்கொள்ளும். ஆனால் இது மக்காவின் இணைவைப்பாளர்களுக்கு மட்டும் ஏற்பட்ட ஒரு பிரமையாக இருந்திருந்தால், \"மக்களைச் சூழ்ந்துகொள்ளும்\" என்று அல்லாஹ் பொதுவாகக் குறிப்பிட்டிருக்க மாட்டான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span><br />\r\n<br />\r\n(இது ஒரு நோவினை தரும் வேதனையாகும்.) அதாவது, இது அவர்களைக் கண்டிக்கும் விதமாக அவர்களிடம் கூறப்படும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُدَعُّونَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">نَارِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَعًّا</span> - <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ</span><br />\r\n<br />\r\n(அவர்கள் நரக நெருப்பின் பால் பலவந்தமாகத் தள்ளப்படும் நாளில், \"இதுதான் நீங்கள் பொய்ப்பித்துக் கொண்டிருந்த நெருப்பு\" (எனக் கூறப்படும்).) (<a href=\"qurandisp.php?sura=52&ayah=13\" class=\"link\">52:13</a>-14). அல்லது அவர்களில் சிலரே மற்றவர்களுக்கு இவ்வாறு கூறுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَّبَّنَا</span> <span class=\"quran-arabic-font text-success\">اكْشِفْ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنُونَ</span><br />\r\n<br />\r\n((அவர்கள் கூறுவார்கள்:) \"எங்கள் இறைவனே! எங்களை விட்டும் இந்த வேதனையை நீக்குவாயாக, நிச்சயமாக நாங்கள் நம்பிக்கையாளர்களாகி விடுகிறோம்!\") அதாவது, நிராகரிப்பாளர்கள் அல்லாஹ்வின் தண்டனையைக் கண்ணாரக் காணும்போது, அதை நீக்கிக் கொள்ளுமாறு இறைஞ்சுவார்கள். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">وُقِفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">يلَيْتَنَا</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُكَذِّبَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">وَنَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(அவர்கள் நெருப்பின் முன் நிறுத்தப்படும்போது நீர் பார்ப்பீராயின், \"நாங்கள் மீண்டும் (உலகிற்கு) அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்ப்பிக்க மாட்டோம்; நம்பிக்கையாளர்களாகவும் இருப்போம்\" என்று கூறுவார்கள்.) (<a href=\"qurandisp.php?sura=6&ayah=27\" class=\"link\">6:27</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرِ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخِّرْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٍ</span> <span class=\"quran-arabic-font text-success\">نُّجِبْ</span> <span class=\"quran-arabic-font text-success\">دَعْوَتَكَ</span> <span class=\"quran-arabic-font text-success\">وَنَتَّبِعِ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلَ</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">أَقْسَمْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زَوَالٍ</span><br />\r\n<br />\r\n(வேதனை அவர்களிடம் வரும் நாளைப் பற்றி மனிதர்களுக்கு எச்சரிக்கை செய்வீராக. அப்போது அநியாயம் செய்தவர்கள், \"எங்கள் இறைவனே! எங்களுக்குச் சிறிது அவகாசம் அளிப்பாயாக; நாங்கள் உன் அழைப்பிற்குப் பதிலளித்து, தூதர்களைப் பின்பற்றுவோம்\" என்று கூறுவார்கள். (அதற்கு அவர்களுக்குச் சொல்லப்படும்:) \"உங்களுக்கு முடிவே இல்லை என்று இதற்கு முன்னால் நீங்கள் சத்தியம் செய்து கொண்டிருக்கவில்லையா?\") (<a href=\"qurandisp.php?sura=14&ayah=44\" class=\"link\">14:44</a>). அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span> <span class=\"quran-arabic-font text-success\">وَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَوَلَّوْاْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مُعَلَّمٌ</span> <span class=\"quran-arabic-font text-success\">مَّجْنُونٌ</span><br />\r\n<br />\r\n(அவர்களுக்கு உபதேசம் எங்கே பயன் தரும்? அவர்களுக்குத் தெளிவான விஷயங்களை விளக்கும் ஒரு தூதர் ஏற்கனவே வந்திருந்தார். பின்னர் அவர்கள் அவரைப் புறக்கணித்துவிட்டு, \"(யாரோ) கற்றுக்கொடுத்தவர், ஒரு பைத்தியக்காரர்\" என்று கூறினார்கள்.) அதாவது, தெளிவான செய்தியுடனும் எச்சரிக்கையுடனும் ஒரு தூதரை நாம் அனுப்பி வைத்த பிறகும், அவர்களுக்கு இன்னும் என்ன உபதேசம் தேவை? இவ்வளவு இருந்தும் அவர்கள் அவரைப் புறக்கணித்து, அவருக்கு எதிராகச் செயல்பட்டு அவரை நிராகரித்தார்கள்; மேலும் \"இவர் மனிதர்களால் கற்றுக்கொடுக்கப்பட்டவர், ஒரு பைத்தியக்காரர்\" என்றும் கூறினார்கள். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n<br />\r\n(அன்றைய நாளில் மனிதன் உணர்வு பெறுவான்; ஆனால் அந்த உணர்வு அவனுக்கு எவ்விதம் பயனளிக்கும்?) (<a href=\"qurandisp.php?sura=89&ayah=23\" class=\"link\">89:23</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">فَزِعُواْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">فَوْتَ</span> <span class=\"quran-arabic-font text-success\">وَأُخِذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّكَانٍ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٍ</span> - <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّى</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">التَّنَاوُشُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مَّكَانِ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ</span><br />\r\n<br />\r\n(அவர்கள் தப்பிக்க வழியின்றித் திடுக்கிடும்போது நீர் பார்ப்பீராயின், அவர்கள் அருகிலுள்ள இடத்திலிருந்தே பிடிக்கப்படுவார்கள். அப்போது அவர்கள், \"நாங்கள் (இப்போது) இதனை நம்புகிறோம்\" என்பார்கள். ஆனால் இவ்வளவு தூரமான இடத்திலிருந்து அவர்கள் எவ்விதம் (நம்பிக்கையை) அடைய முடியும்?) (<a href=\"qurandisp.php?sura=34&ayah=51\" class=\"link\">34:51</a>-52).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كَاشِفُواْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">إِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">عَآئِدُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் வேதனையைச் சிறிது காலத்திற்கு நீக்குவோம்; எனினும் நிச்சயமாக நீங்கள் (மீண்டும் பழைய நிலைக்கே) திரும்புவீர்கள்.) அதாவது, 'நாம் உங்களிடமிருந்து வேதனையைச் சற்று நீக்கி உங்களை மீண்டும் உலகிற்கு அனுப்பி வைத்தாலும், நீங்கள் உங்கள் பழைய நிராகரிப்பு மற்றும் மறுப்பு நிலைக்கே மீண்டும் சென்றுவிடுவீர்கள்.' இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رَحِمْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">وَكَشَفْنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ضُرٍّ</span> <span class=\"quran-arabic-font text-success\">لَّلَجُّواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">طُغْيَـنِهِمْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَهُونَ</span><br />\r\n<br />\r\n(நாம் அவர்கள் மீது கருணை காட்டி அவர்களுக்கு ஏற்பட்ட துன்பத்தை நீக்கினாலும், அவர்கள் தங்கள் வழிகேட்டிலேயே குருட்டுத்தனமாக உழன்று கொண்டிருப்பார்கள்.) (<a href=\"qurandisp.php?sura=23&ayah=75\" class=\"link\">23:75</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">رُدُّواْ</span> <span class=\"quran-arabic-font text-success\">لَعَـدُواْ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">نُهُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ</span><br />\r\n<br />\r\n(அவர்கள் மீண்டும் (உலகிற்குத்) திருப்பி அனுப்பப்பட்டால், எதை விட்டும் அவர்கள் தடுக்கப்பட்டார்களோ அதற்கே மீண்டும் திரும்புவார்கள்; நிச்சயமாக அவர்கள் பொய்யர்களே!) (<a href=\"qurandisp.php?sura=6&ayah=28\" class=\"link\">6:28</a>).<br />\r\n<br />\r\n<strong>\"பெரும் பத்ஷா\" என்பதன் பொருள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">نَبْطِشُ</span> <span class=\"quran-arabic-font text-success\">الْبَطْشَةَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُنتَقِمُونَ</span><br />\r\n<br />\r\n(நாம் பெரும் பிடியாகப் பிடிக்கும் நாளில், நிச்சயமாக நாம் பழிவாங்குவோம்.)<br />\r\n<br />\r\nஇப்னு மஸ்ஊத் (ரழி) அவர்கள் இதற்கு 'பத்ர் போர்' நடந்த நாள் என்று பொருள் கூறினார்கள். புகையைப் பற்றி இப்னு மஸ்ஊத் (ரழி) அவர்களின் கருத்தோடு உடன்பட்ட ஒரு குழுவினரின் கருத்தும் இதுவே. இதே கருத்து இப்னு அப்பாஸ் (ரழி) மற்றும் உபை பின் கஅப் (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. பத்ர் போர் நடந்த நாளும் அல்லாஹ் பழிவாங்கிய நாள்தான் என்பதால் இதுவும் சாத்தியமே; இருப்பினும் வசனத்தின் வெளிப்படையான பொருளின்படி, இது மறுமை நாளைத்தான் குறிக்கிறது. இப்னு ஜரீர் (ரஹ்) அவர்கள் கூறுகிறார்கள்: யாகூப், இப்னு உலைய்யா, காலித் அல்-ஹத்தா ஆகியோர் வழியாக இக்ரிமா கூறினார்கள்: \"இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: 'இப்னு மஸ்ஊத் (ரழி) அவர்கள் பெரும் பிடி (பத்ஷா) என்பது பத்ர் போர் நாள் என்கிறார்கள்; ஆனால் நான் அது மறுமை நாள் என்கிறேன்.'\" இந்த அறிவிப்பாளர் தொடர் இப்னு அப்பாஸ் (ரழி) வரை ஸஹீஹானதாகும். ஹஸன் அல்-பஸரி மற்றும் இக்ரிமா ஆகியோரின் கருத்தும் இதுவேயாகும். அல்லாஹ்வே நன்கறிந்தவன்.<br />\r\n<br />","text":"வானம் தெளிவான புகையைக் கொண்டுவரும் நாளைப் பற்றி இணைவைப்பாளர்களுக்கு எச்சரிக்கை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: இந்த இணைவைப்பாளர்கள் (சத்தியத்தின் மீது) சந்தேகம் கொண்டு விளையாடிக்கொண்டிருக்கிறார்கள். அதாவது, அவர்களிடம் உறுதியான உண்மை வந்துவிட்டது, ஆனால் அவர்கள் அதைச் சந்தேகிப்பதோடு நம்பவும் மறுக்கிறார்கள். பிறகு அல்லாஹ் அவர்களை எச்சரித்தும் அச்சுறுத்தியும் கூறுகிறான்:\n\r\n\n\r\nفَارْتَقِبْ يَوْمَ تَأْتِى السَّمَآءُ بِدُخَانٍ مُّبِينٍ\n\r\n\n\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக.) மஸ்ரூக் (ரஹ்) அவர்கள் கூறியதாவது: \"நாங்கள் கூஃபாவிலுள்ள கிந்தா வாசலுக்கு அருகிலுள்ள ஒரு மஸ்ஜிதிற்குள் நுழைந்தோம். அங்கே ஒரு மனிதர் தம் தோழர்களுக்கு பின்வரும் வசனத்தை ஓதிக்கொண்டிருந்தார்:\n\r\n\n\r\nيَوْمَ تَأْتِى السَّمَآءُ بِدُخَانٍ مُّبِينٍ\n\r\n\n\r\n(வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாள்.) 'அது என்னவென்று உங்களுக்குத் தெரியுமா?' என்று அவர் அவர்களிடம் கேட்டுவிட்டு, 'அது மறுமை நாளில் வரக்கூடிய புகையாகும். அது நயவஞ்சகர்களின் செவிப்புலனையும் பார்வையையும் பறித்துவிடும். ஆனால் நம்பிக்கையாளர்களுக்கு (முஃமின்களுக்கு) அது ஒரு ஜலதோஷம் (சளி) பிடித்ததைப் போன்ற உணர்வைத்தான் ஏற்படுத்தும்' என்றார்.\" மஸ்ரூக் (ரஹ்) மேலும் கூறினார்கள்: \"நாங்கள் இப்னு மஸ்ஊத் (ரழி) அவர்களிடம் வந்து அந்த மனிதர் சொன்னதைப் பற்றிக் கூறினோம். அப்போது அவர்கள் படுத்துக்கொண்டிருந்தார்கள்; இதைக் கேட்டதும் திடுக்கிட்டு எழுந்து அமர்ந்து கூறினார்கள்: 'அல்லாஹ் உங்கள் நபியிடம் (ஸல்) கூறினான்:\n\r\n\n\r\nقُلْ مَآ أَسْـَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَآ مِنَ الْمُتَكَلِّفِينَ\n\r\n\n\r\n(நபியே!) நீர் கூறுவீராக: இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை; மேலும் நான் போலியாகப் பேசுபவனும் (நடிப்பவனும்) அல்ல.' (38:86). ஒரு மனிதருக்குத் தெரியாத ஒரு விஷயத்தைப் பற்றி, 'அல்லாஹ்வே நன்கறிந்தவன்' என்று கூறுவதும் அறிவின் ஒரு பகுதியாகும். இது சம்பந்தமாக ஒரு ஹதீஸை நான் உங்களுக்குக் கூறுகிறேன். குரைஷிகள் இஸ்லாத்தை ஏற்க மறுத்து பிடிவாதம் காட்டியபோது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவர்களுக்கு எதிராக, யூசுஃப் (அலை) அவர்களின் காலத்தில் ஏற்பட்ட பஞ்சத்தைப் போன்ற ஒரு பஞ்சம் அவர்கள் மீது ஏற்பட வேண்டும் என்று அல்லாஹ்விடம் பிரார்த்தித்தார்கள். அதன் விளைவாக அவர்கள் கடும் பசியால் வாடி, எலும்புகளையும் செத்த பிராணிகளையும் உண்ணும் நிலைக்குத் தள்ளப்பட்டார்கள். அவர்கள் வானத்தைப் பார்த்தபோது கடும் பசியினால் அவர்களுக்குப் புகையைப் போலத்தான் தெரிந்தது.\" மற்றொரு அறிவிப்பில்: \"ஒரு மனிதன் தன் பசியின் சோர்வினால் வானத்தைப் பார்க்கும்போது, அவருக்கும் வானத்திற்கும் இடையில் ஒரு புகைமூட்டம் இருப்பதைப் போன்றே காண்பார்\" என்றுள்ளது.\n\r\n\n\r\nفَارْتَقِبْ يَوْمَ تَأْتِى السَّمَآءُ بِدُخَانٍ مُّبِينٍ - يَغْشَى النَّاسَ هَـذَا عَذَابٌ أَلِيمٌ\n\r\n\n\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக. அது மக்களைச் சூழ்ந்துகொள்ளும்; இது ஒரு நோவினை தரும் வேதனையாகும்.) ஒரு மனிதர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, \"அல்லாஹ்வின் தூதரே! முதர் கோத்திரத்தாருக்காக மழை பொழிய அல்லாஹ்விடம் பிரார்த்தியுங்கள், ஏனெனில் அவர்கள் (பஞ்சத்தால்) இறந்துகொண்டிருக்கிறார்கள்\" என்று வேண்டினார். ஆகவே நபி (ஸல்) அவர்கள் அவர்களுக்காக மழை வேண்டினார்கள், மழையும் பொழிந்தது. பின்னர் இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nإِنَّا كَاشِفُواْ الْعَذَابِ قَلِيلاً إِنَّكُمْ عَآئِدُونَ\n\r\n\n\r\n(நிச்சயமாக, நாம் இந்த வேதனையைச் சிறிது காலத்திற்கு நீக்குவோம். எனினும் நிச்சயமாக நீங்கள் (மீண்டும் பழைய நிலைக்கே) திரும்புவீர்கள்.) இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"மறுமை நாளில் வேதனை நீக்கப்படும் என்று நீங்கள் கருதுகிறீர்களா? அவர்களுக்கு இவ்வுலகில் வேதனை நீக்கப்பட்டு வசதி அளிக்கப்பட்டபோது, அவர்கள் மீண்டும் தங்கள் பழைய நிராகரிப்பு நிலைக்கே திரும்பிவிட்டார்கள்.\" அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nيَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنتَقِمُونَ\n\r\n\n\r\n(நாம் பெரும் பிடியாகப் பிடிக்கும் நாளில், நிச்சயமாக நாம் பழிவாங்குவோம்.) இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"இது பத்ர் நாளைக் குறிக்கிறது.\" மேலும் அவர்கள் கூறினார்கள்: \"ஐந்து விஷயங்கள் நிகழ்ந்துவிட்டன: புகை (துக்கான்), ரோமர்களின் வெற்றி, சந்திரன் பிளந்தது, பெரும் பிடி (பத்ஷா), மற்றும் வேதனை.\" இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது. மேலும் இமாம் அஹ்மத், திர்மிதி, நஸாயீ, இப்னு ஜரீர் மற்றும் இப்னு அபீ ஹாதிம் ஆகியோரும் பல அறிவிப்பாளர் தொடர்களின் வழியாக இதனைப் பதிவு செய்துள்ளனர். முஜாஹித், அபுல் ஆலியா, இப்ராஹீம் அந்நகஈ, அத்-தஹ்ஹாக் மற்றும் அதிய்யா அல்-அவ்ஃபீ போன்ற பல ஸலஃபுகள், 'புகை' என்பது ஏற்கனவே நிகழ்ந்துவிட்டது என்ற இப்னு மஸ்ஊத் (ரழி) அவர்களின் கருத்தையே ஏற்றுக்கொண்டனர். இப்னு ஜரீர் என்பவரும் இக்கருத்தையே கொண்டுள்ளார்.\n\r\n\n\r\nஅபூ ஸரீஹா ஹுதைஃபா பின் அஸீத் அல்-கிஃபாரி (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸில் கூறப்பட்டுள்ளதாவது: \"நாங்கள் மறுமை நாளைப் பற்றி விவாதித்துக் கொண்டிருந்தபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓர் அறையிலிருந்து எங்களை நோக்கி வந்து கூறினார்கள்:\n\r\n\n\r\n«لَا تَقُومُ السَّاعَةُ حَتَّى تَرَوْا عَشْرَ آيَاتٍ: طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا، وَالدُّخَانَ، وَالدَّابَّةَ، وَخُرُوجَ يَأْجُوجَ وَمَأْجُوجَ، وَنُزُولَ عِيْسَى ابْنِ مَرْيَمَ وَالدَّجَّالَ، وَثَلَاثَةَ خُسُوفٍ: خَسْفٌ بِالْمَشْرِقِ، وَخَسْفٌ بِالْمَغْرِبِ، وَخَسْفٌ بِجَزِيرَةِ الْعَرَبِ، وَنَارًا تَخْرُجُ مِنْ قَعْرِ عَدَنَ تَسُوقُ النَّاسَ أَوْ تَحْشُرُ النَّاسَ تَبِيتُ مَعَهُمْ حَيْثُ بَاتُوا، وَتَقِيلُ مَعَهُمْ حَيْثُ قَالُوا»\n\r\n\n\r\n(பத்து அடையாளங்களை நீங்கள் காணும் வரை மறுமை நாள் வராது. அவை: சூரியன் மேற்கிலிருந்து உதிப்பது; புகை; (தாப்பத்துல் அர்ள் எனும்) பிராணி; யஃஜூஜ் மற்றும் மஃஜூஜ் ஆகியோரின் வருகை; ஈஸா இப்னு மர்யம் (அலை) அவர்களின் வருகை; தஜ்ஜால்; மூன்று நிலச்சரிவுகள் (பூமி உள்வாங்குதல்) - ஒன்று கிழக்கிலும், ஒன்று மேற்கிலும், மற்றொன்று அரேபிய தீபகற்பத்திலும் ஏற்படும்; இறுதியாக ஏடன் (Aden) பகுதியின் ஆழத்திலிருந்து ஒரு நெருப்பு புறப்பட்டு மக்களை விரட்டிச் செல்லும் - அல்லது மக்களை ஒன்றுதிரட்டும் - அவர்கள் இரவில் தங்கும் இடத்தில் அதுவும் தங்கும், அவர்கள் பகலில் ஓய்வெடுக்கும் இடத்தில் அதுவும் தங்கும்.)\" இதனை இமாம் முஸ்லிம் மட்டும் தமது ஸஹீஹில் பதிவு செய்துள்ளார்.\n\r\n\n\r\nபுகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவாகியுள்ள மற்றுமொரு செய்தியில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இப்னு ஸய்யாதிடம்:\n\r\n\n\r\n«إِنِّي خَبَأْتُ لَكَ خَبْأ»\n\r\n\n\r\n(நான் உனக்காக ஒரு விஷயத்தை மனதிற்குள் மறைத்து வைத்துள்ளேன், அது என்னவென்று சொல்?) என்றார்கள். அதற்கு அவன், 'அது அத்-துக்' (அதாவது புகை) என்றான். நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«اخْسَأْ فَلَنْ تَعْدُوَ قَدْرَك»\n\r\n\n\r\n(இழிவடைந்து போ! உனது தகுதியை உன்னால் தாண்ட முடியாது) என்றார்கள். இப்னு மஸ்ஊத் (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\nفَارْتَقِبْ يَوْمَ تَأْتِى السَّمَآءُ بِدُخَانٍ مُّبِينٍ\n\r\n\n\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக) என்ற வசனத்தைத் தான் அவனிடம் மறைத்து வைத்திருந்தார்கள்.\" புகை என்பது இன்னும் ஏற்படவில்லை என்பதையே இது காட்டுகிறது. இப்னு ஸய்யாத் என்பவன் ஒரு ஜோதிடனாவான்; அவன் ஜின்கள் மூலம் செய்திகளைக் கேட்பான். ஜின்களின் பேச்சு தெளிவாக இருக்காது என்பதால் அவன் 'அத்-துக்கான்' என்று முழுமையாகச் சொல்லாமல் 'அத்-துக்' என்று கூறினான். அவன் தகவல்களைப் பெறுவது ஷைத்தான்கள் மூலமாகத்தான் என்பதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் உறுதி செய்தபோதுதான், \"இழிவடைந்து போ! உனது தகுதியை உன்னால் தாண்ட முடியாது\" என்று கூறினார்கள்.\n\r\n\n\r\nபுகை என்பது இனிமேல் வரப்போகும் மறுமை நாளின் அடையாளங்களில் ஒன்று என்பதை உறுதிப்படுத்தும் ஏராளமான ஸஹீஹ் மற்றும் ஹஸன் தரத்திலான மர்ஃபூஃ (நபியவர்கள் கூறியவை) மற்றும் மவ்கூஃப் (ஸஹாபாக்கள் கூறியவை) ஹதீஸ்கள் உள்ளன. குர்ஆன் வசனங்களின் வெளிப்படையான பொருளும் இதுவேயாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَارْتَقِبْ يَوْمَ تَأْتِى السَّمَآءُ بِدُخَانٍ مُّبِينٍ\n\r\n\n\r\n(ஆகவே, வானம் ஒரு தெளிவான புகையைக் கொண்டுவரும் நாளை நீர் எதிர்பார்ப்பீராக.) அதாவது, அது மக்கள் அனைவருக்கும் தெளிவாகத் தெரியும் வகையில் இருக்கும். இப்னு மஸ்ஊத் (ரழி) அவர்களின் விளக்கப்படி, அது அவர்களின் கடுமையான பசியினால் ஏற்பட்ட ஒரு பிரமையாகும். மேலும் அல்லாஹ்:\n\r\n\n\r\nيَغْشَى النَّاسَ\n\r\n\n\r\n(அது மக்களைச் சூழ்ந்துகொள்ளும்) என்று கூறுகிறான். அதாவது, அது அனைவரையும் மூடி ஆட்கொள்ளும். ஆனால் இது மக்காவின் இணைவைப்பாளர்களுக்கு மட்டும் ஏற்பட்ட ஒரு பிரமையாக இருந்திருந்தால், \"மக்களைச் சூழ்ந்துகொள்ளும்\" என்று அல்லாஹ் பொதுவாகக் குறிப்பிட்டிருக்க மாட்டான்.\n\r\n\n\r\nهَـذَا عَذَابٌ أَلِيمٌ\n\r\n\n\r\n(இது ஒரு நோவினை தரும் வேதனையாகும்.) அதாவது, இது அவர்களைக் கண்டிக்கும் விதமாக அவர்களிடம் கூறப்படும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nيَوْمَ يُدَعُّونَ إِلَى نَارِ جَهَنَّمَ دَعًّا - هَـذِهِ النَّارُ الَّتِى كُنتُم بِهَا تُكَذِّبُونَ\n\r\n\n\r\n(அவர்கள் நரக நெருப்பின் பால் பலவந்தமாகத் தள்ளப்படும் நாளில், \"இதுதான் நீங்கள் பொய்ப்பித்துக் கொண்டிருந்த நெருப்பு\" (எனக் கூறப்படும்).) (52:13-14). அல்லது அவர்களில் சிலரே மற்றவர்களுக்கு இவ்வாறு கூறுவார்கள்.\n\r\n\n\r\nرَّبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ\n\r\n\n\r\n((அவர்கள் கூறுவார்கள்:) \"எங்கள் இறைவனே! எங்களை விட்டும் இந்த வேதனையை நீக்குவாயாக, நிச்சயமாக நாங்கள் நம்பிக்கையாளர்களாகி விடுகிறோம்!\") அதாவது, நிராகரிப்பாளர்கள் அல்லாஹ்வின் தண்டனையைக் கண்ணாரக் காணும்போது, அதை நீக்கிக் கொள்ளுமாறு இறைஞ்சுவார்கள். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nوَلَوْ تَرَى إِذْ وُقِفُواْ عَلَى النَّارِ فَقَالُواْ يلَيْتَنَا نُرَدُّ وَلاَ نُكَذِّبَ بِـَايَـتِ رَبِّنَا وَنَكُونَ مِنَ الْمُؤْمِنِينَ\n\r\n\n\r\n(அவர்கள் நெருப்பின் முன் நிறுத்தப்படும்போது நீர் பார்ப்பீராயின், \"நாங்கள் மீண்டும் (உலகிற்கு) அனுப்பப்பட்டால் எவ்வளவு நன்றாக இருக்கும்! அப்போது நாங்கள் எங்கள் இறைவனின் வசனங்களைப் பொய்ப்பிக்க மாட்டோம்; நம்பிக்கையாளர்களாகவும் இருப்போம்\" என்று கூறுவார்கள்.) (6:27).\n\r\n\n\r\nوَأَنذِرِ النَّاسَ يَوْمَ يَأْتِيهِمُ الْعَذَابُ فَيَقُولُ الَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرْنَآ إِلَى أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ الرُّسُلَ أَوَلَمْ تَكُونُواْ أَقْسَمْتُمْ مِّن قَبْلُ مَا لَكُمْ مِّن زَوَالٍ\n\r\n\n\r\n(வேதனை அவர்களிடம் வரும் நாளைப் பற்றி மனிதர்களுக்கு எச்சரிக்கை செய்வீராக. அப்போது அநியாயம் செய்தவர்கள், \"எங்கள் இறைவனே! எங்களுக்குச் சிறிது அவகாசம் அளிப்பாயாக; நாங்கள் உன் அழைப்பிற்குப் பதிலளித்து, தூதர்களைப் பின்பற்றுவோம்\" என்று கூறுவார்கள். (அதற்கு அவர்களுக்குச் சொல்லப்படும்:) \"உங்களுக்கு முடிவே இல்லை என்று இதற்கு முன்னால் நீங்கள் சத்தியம் செய்து கொண்டிருக்கவில்லையா?\") (14:44). அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nأَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَآءَهُمْ رَسُولٌ مُّبِينٌ - ثُمَّ تَوَلَّوْاْ عَنْهُ وَقَالُواْ مُعَلَّمٌ مَّجْنُونٌ\n\r\n\n\r\n(அவர்களுக்கு உபதேசம் எங்கே பயன் தரும்? அவர்களுக்குத் தெளிவான விஷயங்களை விளக்கும் ஒரு தூதர் ஏற்கனவே வந்திருந்தார். பின்னர் அவர்கள் அவரைப் புறக்கணித்துவிட்டு, \"(யாரோ) கற்றுக்கொடுத்தவர், ஒரு பைத்தியக்காரர்\" என்று கூறினார்கள்.) அதாவது, தெளிவான செய்தியுடனும் எச்சரிக்கையுடனும் ஒரு தூதரை நாம் அனுப்பி வைத்த பிறகும், அவர்களுக்கு இன்னும் என்ன உபதேசம் தேவை? இவ்வளவு இருந்தும் அவர்கள் அவரைப் புறக்கணித்து, அவருக்கு எதிராகச் செயல்பட்டு அவரை நிராகரித்தார்கள்; மேலும் \"இவர் மனிதர்களால் கற்றுக்கொடுக்கப்பட்டவர், ஒரு பைத்தியக்காரர்\" என்றும் கூறினார்கள். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَوْمَئِذٍ يَتَذَكَّرُ الإِنسَـنُ وَأَنَّى لَهُ الذِّكْرَى\n\r\n\n\r\n(அன்றைய நாளில் மனிதன் உணர்வு பெறுவான்; ஆனால் அந்த உணர்வு அவனுக்கு எவ்விதம் பயனளிக்கும்?) (89:23).\n\r\n\n\r\nوَلَوْ تَرَى إِذْ فَزِعُواْ فَلاَ فَوْتَ وَأُخِذُواْ مِن مَّكَانٍ قَرِيبٍ - وَقَالُواْ ءَامَنَّا بِهِ وَأَنَّى لَهُمُ التَّنَاوُشُ مِن مَّكَانِ بَعِيدٍ\n\r\n\n\r\n(அவர்கள் தப்பிக்க வழியின்றித் திடுக்கிடும்போது நீர் பார்ப்பீராயின், அவர்கள் அருகிலுள்ள இடத்திலிருந்தே பிடிக்கப்படுவார்கள். அப்போது அவர்கள், \"நாங்கள் (இப்போது) இதனை நம்புகிறோம்\" என்பார்கள். ஆனால் இவ்வளவு தூரமான இடத்திலிருந்து அவர்கள் எவ்விதம் (நம்பிக்கையை) அடைய முடியும்?) (34:51-52).\n\r\n\n\r\nإِنَّا كَاشِفُواْ الْعَذَابِ قَلِيلاً إِنَّكُمْ عَآئِدُونَ\n\r\n\n\r\n(நிச்சயமாக நாம் வேதனையைச் சிறிது காலத்திற்கு நீக்குவோம்; எனினும் நிச்சயமாக நீங்கள் (மீண்டும் பழைய நிலைக்கே) திரும்புவீர்கள்.) அதாவது, 'நாம் உங்களிடமிருந்து வேதனையைச் சற்று நீக்கி உங்களை மீண்டும் உலகிற்கு அனுப்பி வைத்தாலும், நீங்கள் உங்கள் பழைய நிராகரிப்பு மற்றும் மறுப்பு நிலைக்கே மீண்டும் சென்றுவிடுவீர்கள்.' இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nوَلَوْ رَحِمْنَـهُمْ وَكَشَفْنَا مَا بِهِمْ مِّن ضُرٍّ لَّلَجُّواْ فِى طُغْيَـنِهِمْ يَعْمَهُونَ\n\r\n\n\r\n(நாம் அவர்கள் மீது கருணை காட்டி அவர்களுக்கு ஏற்பட்ட துன்பத்தை நீக்கினாலும், அவர்கள் தங்கள் வழிகேட்டிலேயே குருட்டுத்தனமாக உழன்று கொண்டிருப்பார்கள்.) (23:75).\n\r\n\n\r\nوَلَوْ رُدُّواْ لَعَـدُواْ لِمَا نُهُواْ عَنْهُ وَإِنَّهُمْ لَكَـذِبُونَ\n\r\n\n\r\n(அவர்கள் மீண்டும் (உலகிற்குத்) திருப்பி அனுப்பப்பட்டால், எதை விட்டும் அவர்கள் தடுக்கப்பட்டார்களோ அதற்கே மீண்டும் திரும்புவார்கள்; நிச்சயமாக அவர்கள் பொய்யர்களே!) (6:28).\n\r\n\n\r\n\"பெரும் பத்ஷா\" என்பதன் பொருள்\n\r\n\n\r\nيَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنتَقِمُونَ\n\r\n\n\r\n(நாம் பெரும் பிடியாகப் பிடிக்கும் நாளில், நிச்சயமாக நாம் பழிவாங்குவோம்.)\n\r\n\n\r\nஇப்னு மஸ்ஊத் (ரழி) அவர்கள் இதற்கு 'பத்ர் போர்' நடந்த நாள் என்று பொருள் கூறினார்கள். புகையைப் பற்றி இப்னு மஸ்ஊத் (ரழி) அவர்களின் கருத்தோடு உடன்பட்ட ஒரு குழுவினரின் கருத்தும் இதுவே. இதே கருத்து இப்னு அப்பாஸ் (ரழி) மற்றும் உபை பின் கஅப் (ரழி) ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. பத்ர் போர் நடந்த நாளும் அல்லாஹ் பழிவாங்கிய நாள்தான் என்பதால் இதுவும் சாத்தியமே; இருப்பினும் வசனத்தின் வெளிப்படையான பொருளின்படி, இது மறுமை நாளைத்தான் குறிக்கிறது. இப்னு ஜரீர் (ரஹ்) அவர்கள் கூறுகிறார்கள்: யாகூப், இப்னு உலைய்யா, காலித் அல்-ஹத்தா ஆகியோர் வழியாக இக்ரிமா கூறினார்கள்: \"இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: 'இப்னு மஸ்ஊத் (ரழி) அவர்கள் பெரும் பிடி (பத்ஷா) என்பது பத்ர் போர் நாள் என்கிறார்கள்; ஆனால் நான் அது மறுமை நாள் என்கிறேன்.'\" இந்த அறிவிப்பாளர் தொடர் இப்னு அப்பாஸ் (ரழி) வரை ஸஹீஹானதாகும். ஹஸன் அல்-பஸரி மற்றும் இக்ரிமா ஆகியோரின் கருத்தும் இதுவேயாகும். அல்லாஹ்வே நன்கறிந்தவன்."},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=33\" class=\"link\">44:33</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:33 ஐ பார்க்கவும்"},"33":{"html":"<strong>மூஸா (அலை) மற்றும் ஃபிர்அவ்னின் வரலாறு, மேலும் பனூ இஸ்ராயீல் மக்கள் எவ்வாறு காப்பாற்றப்பட்டார்கள்</strong><br />\r\n<br />\r\n<br />\r\n'இந்த இணைவைப்பாளர்களுக்கு முன்பாக, ஃபிர்அவ்னின் மக்களான எகிப்தின் கிப்தி (Copts) இனத்தவரை நாம் சோதித்தோம்' என்று அல்லாஹ் கூறுகிறான். <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">فَتَنَّا</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ﴿</span> <span class=\"quran-arabic-font text-success\">﴾وَجَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(கண்ணியமிக்க ஒரு தூதர் அவர்களிடம் வந்தபோது) என்பது, அல்லாஹ் நேரடியாகப் பேசிய மூஸா (அலை) அவர்களைக் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾أَنْ</span> <span class=\"quran-arabic-font text-success\">أَدُّواْ</span> <span class=\"quran-arabic-font text-success\">إِلَىَّ</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n<br />\r\n(அல்லாஹ்வின் அடியார்களை என்னிடம் ஒப்படைத்துவிடுங்கள்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾فَأَرْسِلْ</span> <span class=\"quran-arabic-font text-success\">مَعَنَا</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُعَذِّبْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">جِئْنَـكَ</span> <span class=\"quran-arabic-font text-success\">بِـَايَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">وَالسَّلَـمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَ</span> <span class=\"quran-arabic-font text-success\">الْهُدَى﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆகவே, பனூ இஸ்ராயீல் மக்களை எங்களுடன் அனுப்பிவிடும், அவர்களைத் துன்புறுத்தாதீர்; நிச்சயமாக நாம் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்திருக்கிறோம்! மேலும், நேர்வழியைப் பின்பற்றுவோர் மீது சாந்தி நிலவட்டும்!) (<a href=\"qurandisp.php?sura=20&ayah=47\" class=\"link\">20:47</a>) <span class=\"quran-arabic-font text-success\">﴾إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">أَمِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய ஒரு தூதராவேன்) என்பதன் பொருள், 'நான் உங்களுக்கு எத்திவைக்கும் செய்திகள் நம்பகமானவை' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَأَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَعْلُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அல்லாஹ்வுக்கு எதிராகப் பெருமையடிக்காதீர்கள்) என்பதன் பொருள், 'அவனுடைய அத்தாட்சிகளைப் பின்பற்றுவதில் ஆணவம் கொள்ளாதீர்கள். அவனுடைய ஆதாரங்களை ஏற்றுக்கொண்டு, அவனுடைய சான்றுகளை நம்புங்கள்' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَكْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادَتِى</span> <span class=\"quran-arabic-font text-success\">سَيَدْخُلُونَ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَخِرِينَ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள், சிறுமைப்பட்டவர்களாக நரகத்தில் நுழைவார்கள்!) (<a href=\"qurandisp.php?sura=40&ayah=60\" class=\"link\">40:60</a>) <span class=\"quran-arabic-font text-success\">﴾إِنِّى</span> <span class=\"quran-arabic-font text-success\">ءَاتِيكُمْ</span> <span class=\"quran-arabic-font text-success\">بِسُلْطَانٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, நான் உங்களிடம் தெளிவான ஆதாரத்துடன் வந்திருக்கிறேன்) என்பதன் பொருள், வெளிப்படையான அத்தாட்சியுடன் என்பதாகும். இது அல்லாஹ் அவரை அனுப்பிவைத்த தெளிவான அடையாளங்களையும் உறுதியான சான்றுகளையும் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾وَإِنِّى</span> <span class=\"quran-arabic-font text-success\">عُذْتُ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَرْجُمُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நிச்சயமாக, நீங்கள் என்னைக் கல்லெறிந்து கொல்லாமலிருக்க, என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன்.) இப்னு அப்பாஸ் (ரழி) அவர்களும், அபூ ஸாலிஹ் அவர்களும், \"இது வாய்மொழித் தாக்குதலையும் அவதூறுகளையும் குறிக்கிறது\" என்று கூறினார்கள். கத்தாதா அவர்கள், \"இதன் பொருள் நேரடியான 'கல்லெறிதல்' என்பதாகும். அதாவது: 'என்னையும் உங்களையும் படைத்த அல்லாஹ்விடம், உங்களின் தீய சொற்களோ அல்லது செயல்களோ என்னை நெருங்காதிருக்க நான் பாதுகாப்புத் தேடுகிறேன்' என்பதாகும்'' என்று கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">فَاعْتَزِلُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் என்னை நம்பவில்லை என்றால், என்னை விட்டு விலகி விடுங்கள்) என்பதன் பொருள், 'அல்லாஹ் நமக்கிடையே தீர்ப்பளிக்கும் வரை நாம் ஒருவரையொருவர் தொந்தரவு செய்யாமல் விலகி இருப்போம்' என்பதாகும். மூஸா (அலை) அவர்கள் நீண்ட காலம் அவர்களிடையே தங்கியிருந்து, அல்லாஹ்வின் அத்தாட்சிகள் அவர்களுக்கு எதிராக நிலைநாட்டப்பட்ட பின்னரும், அது அவர்களின் நிராகரிப்பையும் பிடிவாதத்தையும் மட்டுமே அதிகரித்தது. எனவே, அவர் அவர்களுக்கு எதிராகத் தனது இறைவனிடம் பிரார்த்தித்தார்கள்; அந்தப் பிரார்த்தனை ஏற்றுக்கொள்ளப்பட்டது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">ءاتَيْتَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَمَلاّهُ</span> <span class=\"quran-arabic-font text-success\">زِينَةً</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">لِيُضِلُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِكَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اطْمِسْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَمْوَلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَاشْدُدْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الاٌّلِيمَ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أُجِيبَتْ</span> <span class=\"quran-arabic-font text-success\">دَّعْوَتُكُمَا</span> <span class=\"quran-arabic-font text-success\">فَاسْتَقِيمَا﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் மூஸா கூறினார்கள்: \"எங்கள் இறைவனே! நீ ஃபிர்அவ்னுக்கும் அவனுடைய தலைவர்களுக்கும் இவ்வுலக வாழ்வில் அலங்காரத்தையும் செல்வங்களையும் நிச்சயமாக வழங்கியுள்ளாய். எங்கள் இறைவனே! அவர்கள் உனது பாதையிலிருந்து (மக்களை) வழிதவறச் செய்வதற்காகவே (இவற்றை உபயோகிக்கின்றனர்). எங்கள் இறைவனே! அவர்களின் செல்வங்களை அழித்து, அவர்களின் இதயங்களைக் கடினமாக்கிவிடுவாயாக! துன்புறுத்தும் வேதனையைக் காணும் வரை அவர்கள் ஈமான் கொள்ள மாட்டார்கள்.\" அல்லாஹ் கூறினான்: \"உங்கள் இருவரின் பிரார்த்தனையும் நிச்சயமாக ஏற்கப்பட்டது. எனவே, நீங்கள் இருவரும் நேர்வழியில் உறுதியாக இருங்கள்.\") (<a href=\"qurandisp.php?sura=10&ayah=88\" class=\"link\">10:88</a>-89) மேலும் அல்லாஹ் இங்கே கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَدَعَا</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">مُّجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(எனவே அவர் (மூஸா) தனது இறைவனிடம், \"நிச்சயமாக இவர்கள் குற்றவாளிகளான மக்கள்\" என்று பிரார்த்தித்தார்கள்.) அதன் பிறகு அல்லாஹ், ஃபிர்அவ்னின் சம்மதமோ அனுமதியோ இன்றி பனூ இஸ்ராயீல் மக்களை அங்கிருந்து வெளியே அழைத்துச் செல்லுமாறு அவருக்குக் கட்டளையிட்டான். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾فَأَسْرِ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادِى</span> <span class=\"quran-arabic-font text-success\">لَيْلاً</span> <span class=\"quran-arabic-font text-success\">إِنَّكُم</span> <span class=\"quran-arabic-font text-success\">مُّتَّبَعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(எனது அடியார்களை அழைத்துக் கொண்டு இரவோடு இரவாகப் புறப்படுங்கள். நிச்சயமாக நீங்கள் பின்தொடரப்படுவீர்கள்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَوْحَيْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَسْرِ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادِى</span> <span class=\"quran-arabic-font text-success\">فَاضْرِبْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَرِيقاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">يَبَساً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَخَافُ</span> <span class=\"quran-arabic-font text-success\">دَرَكاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَخْشَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நாம் மூஸா (அலை) அவர்களுக்கு வஹீ (இறைச்செய்தி) அறிவித்தோம்: \"எனது அடியார்களை அழைத்துக் கொண்டு இரவில் பயணம் செய்வீராக! (எதிரிகளால்) பிடிக்கப்படுவோம் என்றோ அல்லது (கடலில் மூழ்கிவிடுவோம் என்றோ) அஞ்சாமல், கடலில் அவர்களுக்காக ஒரு உலர்ந்த பாதையை ஏற்படுத்துவீராக!\") (<a href=\"qurandisp.php?sura=20&ayah=77\" class=\"link\">20:77</a>) <span class=\"quran-arabic-font text-success\">﴾وَاتْرُكِ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَ</span> <span class=\"quran-arabic-font text-success\">رَهْواً</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">جُندٌ</span> <span class=\"quran-arabic-font text-success\">مُّغْرَقُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் கடலை அது இருந்தவாறே (அமைதியாகவும் பிளவுபட்டும்) விட்டுவிடுவீராக. நிச்சயமாக, அவர்கள் மூழ்கடிக்கப்பட வேண்டிய ஒரு படையினராவர்.) மூஸா (அலை) அவர்களும் பனூ இஸ்ராயீல் மக்களும் கடலைக் கடந்ததும், மூஸா (அலை) அவர்கள் தனது கைத்தடியால் கடலை மீண்டும் அடிக்க விரும்பினார்கள். அவ்வாறு செய்தால் கடல் பழைய நிலைக்குத் திரும்பி, ஃபிர்அவ்ன் தங்களைப் பின்தொடர முடியாதவாறு தடையாக இருக்கும் என்று அவர்கள் கருதினார்கள். ஆனால் அல்லாஹ் அதை அப்படியே அமைதியாகவும் பிளவுபட்டும் விட்டுவிடுமாறு கட்டளையிட்டான். அவர்கள் அனைவரும் மூழ்கடிக்கப்படுவார்கள் என்ற நற்செய்தியை அவருக்கு வழங்கி, ஃபிர்அவ்னால் பிடிக்கப்படுவோம் என்றோ கடலில் மூழ்கிவிடுவோம் என்றோ அஞ்ச வேண்டாம் என்றும் கூறினான். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَاتْرُكِ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَ</span> <span class=\"quran-arabic-font text-success\">رَهْواً﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் கடலை அது இருந்தவாறே விட்டுவிடுவீராக.) என்பதன் பொருள், அதை அப்படியே விட்டுவிட்டு தொடர்ந்து முன்னேறிச் செல்லுங்கள் என்பதாகும். முஜாஹித் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾رَهْواً﴿</span><br />\r\n<br />\r\n<br />\r\n(இருந்தவாறே) என்பதன் பொருள், உலர்ந்த பாதையாக, அது இருந்த அதே நிலையில் என்பதாகும். 'கடல் மீண்டும் பழைய நிலைக்குத் திரும்பக் கட்டளையிட வேண்டாம்; அவர்களின் இறுதி ஆள் நுழையும் வரை அதை அப்படியே விட்டுவிடுங்கள்.' இக்ரிமா, அர்-ரபீஃ பின் அனஸ், அத்-தஹ்ஹாக், கத்தாதா, இப்னு ஸைத், கஅப் அல்-அஹ்பார், சிமாக் பின் ஹர்ப் மற்றும் பலரும் இதே கருத்தைக் கொண்டிருந்தனர். <span class=\"quran-arabic-font text-success\">﴾كَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَكُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">وَعُيُونٍ</span> <span class=\"quran-arabic-font text-success\">وَزُرُوعٍ﴿</span><br />\r\n<br />\r\n<br />\r\n(எத்தனை சோலைகளையும் நீரூற்றுகளையும் அவர்கள் விட்டுச் சென்றார்கள்! இன்னும் பசுமையான பயிர்களையும்.) இது ஆறுகளையும் கிணறுகளையும் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾وَمَقَامٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ﴿</span><br />\r\n<br />\r\n<br />\r\nமேலும் கண்ணியமிக்க இடங்களையும் - இதன் பொருள் சிறந்த இருப்பிடங்கள் மற்றும் அழகான இடங்கள் என்பதாகும். முஜாஹித் அவர்களும் ஸயீத் பின் ஜுபைர் அவர்களும்: <span class=\"quran-arabic-font text-success\">﴾وَمَقَامٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ﴿</span><br />\r\n<br />\r\n<br />\r\n(கண்ணியமிக்க இடங்கள்) என்பது உயர்ந்த இடங்களைக் குறிக்கும் என்று கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾وَنَعْمَةٍ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَـكِهِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்கள் அனுபவித்து வந்த சுகபோகங்களையும்!) என்பதன் பொருள், அவர்கள் அனுபவித்த வாழ்க்கை வசதிகள்; அவர்கள் விரும்பியதைச் சாப்பிடவும், விரும்பியதை உடுத்தவும், செல்வத்தோடும் அதிகாரத்தோடும் அந்த தேசத்தில் வாழ்ந்தார்கள். பின்னர் இவை அனைத்தும் ஒரே காலையில் பறிக்கப்பட்டன. அவர்கள் இவ்வுலகை விட்டு நீங்கி நரகத்திற்குச் சென்றார்கள். அது எவ்வளவு மிக மோசமான தங்குமிடம்! <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَأَوْرَثْنَـهَا</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">ءَاخَرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(இவ்வாறே நடந்தது! மற்றுமொரு சமூகத்தை அவற்றுக்கு வாரிசாக்கினோம்.) அதாவது பனூ இஸ்ராயீல் மக்களை. <span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">بَكَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضُ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்களுக்காக வானமும் பூமியும் அழவில்லை.) அதாவது, வானத்தின் வாயில்கள் வழியாக ஏறிச் செல்லக்கூடிய எந்த நற்செயல்களும் அவர்களிடம் இல்லை. பொதுவாக ஒரு நம்பிக்கையாளர் இறக்கும்போது அவருக்காக வானம் அழும். மேலும், அல்லாஹ்வை வணங்குவதற்காகப் பூமியில் அவர்களுக்கு எந்த இடமும் இருக்கவில்லை. எனவே, அவர்களின் குஃப்ரு (நிராகரிப்பு), பாவம் மற்றும் பிடிவாதத்தின் காரணமாக அவர்களுக்கு எவ்வித அவகாசமும் வழங்கப்படவில்லை. இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள்: ஸயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள்: ஒரு மனிதர் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் வந்து, \"ஓ அபூ அப்பாஸ் அவர்களே! <span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">بَكَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">مُنظَرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அவர்களுக்காக வானமும் பூமியும் அழவில்லை; அவர்களுக்கு அவகாசமும் அளிக்கப்படவில்லை) என்று அல்லாஹ் கூறுகிறானே, வானமும் பூமியும் யாருக்காகவாவது அழுகின்றனவா?\" என்று கேட்டார். அதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஆம், வானத்தில் ஒவ்வொரு மனிதருக்கும் ஒரு வாயில் உண்டு. அதன் வழியாகவே அவருடைய வாழ்வாதாரம் இறங்குகிறது, அவருடைய நற்செயல்கள் மேலே ஏறிச் செல்கின்றன. ஒரு முஃமின் (நம்பிக்கையாளர்) மரணிக்கும்போது, அந்த வாயில் மூடப்படுகிறது. அது அவரை இழந்து அவருக்காக அழுகிறது. அவ்வாறே அவர் பூமியில் தொழுது அல்லாஹ்வை நினைவு கூர்ந்த இடங்களும் அவருக்காக அழுகின்றன. ஆனால் ஃபிர்அவ்னின் மக்கள் பூமியில் எந்த நற்செயலையும் விட்டுச் செல்லவில்லை, அவர்களின் எந்த நற்செயலும் அல்லாஹ்விடம் ஏறிச் செல்லவில்லை. எனவேதான் வானமும் பூமியும் அவர்களுக்காக அழவில்லை.\" அல்-அவ்ஃபீ அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இவ்வாறே அறிவித்துள்ளார்கள். <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">نَجَّيْنَا</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْمُهِينِ</span> - <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَالِياً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْرِفِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக நாம் பனூ இஸ்ராயீல் மக்களை இழிவுபடுத்தும் வேதனையிலிருந்து காப்பாற்றினோம் - ஃபிர்அவ்னிடமிருந்து; நிச்சயமாக அவன் வரம்பு மீறியவர்களில் ஒருவனாகவும் ஆணவம் கொண்டவனாகவும் இருந்தான்.) ஃபிர்அவ்னின் பிடியில் அவர்கள் சிக்கித் தவித்தபோது, கடினமான வேலைகளைச் செய்யக் கட்டாயப்படுத்தப்பட்ட இழிவிலிருந்தும் அடிமைத்தனத்திலிருந்தும் அல்லாஹ் அவர்களை எப்படிக் காப்பாற்றினான் என்பதை இங்கே நினைவூட்டுகிறான். <span class=\"quran-arabic-font text-success\">﴾مِن</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَالِياً﴿</span><br />\r\n<br />\r\n<br />\r\n(ஃபிர்அவ்னிடமிருந்து; நிச்சயமாக அவன் ஆணவம் கொண்டவனாக இருந்தான்.) அதாவது, அவன் பெருமையும் பிடிவாதமும் கொண்டவனாக இருந்தான். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">عَلاَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, ஃபிர்அவ்ன் பூமியில் தன்னை உயர்த்திக் கொண்டான்.) (<a href=\"qurandisp.php?sura=28&ayah=4\" class=\"link\">28:4</a>). <span class=\"quran-arabic-font text-success\">﴾فَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">عَـلِينَ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆனால் அவர்கள் பெருமையடித்தார்கள்; அவர்கள் தங்களை உயர்த்திக் கொள்ளும் மக்களாக இருந்தார்கள்.) (<a href=\"qurandisp.php?sura=23&ayah=46\" class=\"link\">23:46</a>). அவன் வரம்பு மீறியவனாகவும், தன்னைப் பற்றி மிகையான தற்பெருமை கொண்டவனாகவும் இருந்தான். <span class=\"quran-arabic-font text-success\">﴾وَلَقَدِ</span> <span class=\"quran-arabic-font text-success\">اخْتَرْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் நாம் அறிந்து கொண்டே அவர்களை அக்கால உலகத்தாரை விட மேலாகத் தேர்ந்தெடுத்தோம்.) \"அவர்கள் வாழ்ந்த காலத்தில் இருந்த மற்ற மக்களை விட அவர்கள் தேர்ந்தெடுக்கப்பட்டார்கள்\" என்று முஜாஹித் அவர்கள் கூறினார்கள். கத்தாதா அவர்கள் கூறுகையில், \"அவர்கள் தங்கள் காலத்து மக்களை விடத் தேர்ந்தெடுக்கப்பட்டனர். ஒவ்வொரு காலக்கட்டத்திலும் மற்றவர்களை விடச் சிறந்த மக்கள் தேர்ந்தெடுக்கப்படுகின்றனர்\" என்றார். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">يَمُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنْى</span> <span class=\"quran-arabic-font text-success\">اصْطَفَيْتُكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ﴿</span><br />\r\n<br />\r\n<br />\r\n(அல்லாஹ் கூறினான்: \"மூஸாவே! நான் உன்னை மக்களில் தேர்ந்தெடுத்துள்ளேன்.\") (<a href=\"qurandisp.php?sura=7&ayah=144\" class=\"link\">7:144</a>). அதாவது அவரது காலத்து மக்களை விட. இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَاصْطَفَـكِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نِسَآءِ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் (அல்லாஹ்) உன்னை (மர்யம்) அகிலத்துப் பெண்களை விடத் தேர்ந்தெடுத்திருக்கிறான்.) (<a href=\"qurandisp.php?sura=3&ayah=42\" class=\"link\">3:42</a>). அதாவது, மர்யம் (அலை) அவர்கள் தனது காலத்துப் பெண்களை விடத் தேர்ந்தெடுக்கப்பட்டார்கள். கதீஜா (ரழி) அவர்கள் மர்யம் (அலை) அவர்களுக்கு இணையானவர்கள் அல்லது அவர்களை விட அந்தஸ்தில் உயர்ந்தவர்கள். ஃபிர்அவ்னின் மனைவியான ஆசியா பின்த் முஸாஹிம் (ரழி) அவர்களும் அவ்வாறே. மேலும், மற்ற அனைத்துப் பெண்களையும் விட ஆயிஷா (ரழி) அவர்களின் சிறப்பானது, மற்ற எல்லா உணவுகளையும் விட 'தரீத்' (Tharid) எனும் உணவின் சிறப்பைப் போன்றதாகும். <span class=\"quran-arabic-font text-success\">﴾وَءَاتَيْنَـهُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الاٌّيَـتِ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அவர்களுக்கு அத்தாட்சிகளை வழங்கினோம்) என்பதன் பொருள் தெளிவான ஆதாரங்கள் மற்றும் அசாத்தியமான சான்றுகள் என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">بَلَؤٌاْ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(அதில் தெளிவானதொரு சோதனை இருந்தது) என்பதன் பொருள், அதன் மூலம் யார் நேர்வழி பெறுகிறார்கள் என்பதைக் கண்டறிய வைக்கப்பட்ட பகிரங்கமான சோதனை என்பதாகும்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மூஸா (அலை) மற்றும் ஃபிர்அவ்னின் வரலாறு, மேலும் பனூ இஸ்ராயீல் மக்கள் எவ்வாறு காப்பாற்றப்பட்டார்கள்\n\r\n\n\r\n\n\r\n'இந்த இணைவைப்பாளர்களுக்கு முன்பாக, ஃபிர்அவ்னின் மக்களான எகிப்தின் கிப்தி (Copts) இனத்தவரை நாம் சோதித்தோம்' என்று அல்லாஹ் கூறுகிறான். ﴾وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ﴿ ﴾وَجَآءَهُمْ رَسُولٌ كَرِيمٌ﴿\n\r\n\n\r\n\n\r\n(கண்ணியமிக்க ஒரு தூதர் அவர்களிடம் வந்தபோது) என்பது, அல்லாஹ் நேரடியாகப் பேசிய மூஸா (அலை) அவர்களைக் குறிக்கிறது. ﴾أَنْ أَدُّواْ إِلَىَّ عِبَادَ اللَّهِ﴿\n\r\n\n\r\n\n\r\n(அல்லாஹ்வின் அடியார்களை என்னிடம் ஒப்படைத்துவிடுங்கள்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾فَأَرْسِلْ مَعَنَا بَنِى إِسْرَءِيلَ وَلاَ تُعَذِّبْهُمْ قَدْ جِئْنَـكَ بِـَايَةٍ مِّن رَّبِّكَ وَالسَّلَـمُ عَلَى مَنِ اتَّبَعَ الْهُدَى﴿\n\r\n\n\r\n\n\r\n(ஆகவே, பனூ இஸ்ராயீல் மக்களை எங்களுடன் அனுப்பிவிடும், அவர்களைத் துன்புறுத்தாதீர்; நிச்சயமாக நாம் உமது இறைவனிடமிருந்து ஓர் அத்தாட்சியுடன் வந்திருக்கிறோம்! மேலும், நேர்வழியைப் பின்பற்றுவோர் மீது சாந்தி நிலவட்டும்!) (20:47) ﴾إِنِّي لَكُمْ رَسُولٌ أَمِينٌ ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய ஒரு தூதராவேன்) என்பதன் பொருள், 'நான் உங்களுக்கு எத்திவைக்கும் செய்திகள் நம்பகமானவை' என்பதாகும். ﴾وَأَن لاَّ تَعْلُواْ عَلَى اللَّهِ﴿\n\r\n\n\r\n\n\r\n(மேலும், அல்லாஹ்வுக்கு எதிராகப் பெருமையடிக்காதீர்கள்) என்பதன் பொருள், 'அவனுடைய அத்தாட்சிகளைப் பின்பற்றுவதில் ஆணவம் கொள்ளாதீர்கள். அவனுடைய ஆதாரங்களை ஏற்றுக்கொண்டு, அவனுடைய சான்றுகளை நம்புங்கள்' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَخِرِينَ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக, எனது வணக்கத்தைப் புறக்கணித்துப் பெருமையடிப்பவர்கள், சிறுமைப்பட்டவர்களாக நரகத்தில் நுழைவார்கள்!) (40:60) ﴾إِنِّى ءَاتِيكُمْ بِسُلْطَانٍ مُّبِينٍ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக, நான் உங்களிடம் தெளிவான ஆதாரத்துடன் வந்திருக்கிறேன்) என்பதன் பொருள், வெளிப்படையான அத்தாட்சியுடன் என்பதாகும். இது அல்லாஹ் அவரை அனுப்பிவைத்த தெளிவான அடையாளங்களையும் உறுதியான சான்றுகளையும் குறிக்கிறது. ﴾وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ ﴿\n\r\n\n\r\n\n\r\n(மேலும் நிச்சயமாக, நீங்கள் என்னைக் கல்லெறிந்து கொல்லாமலிருக்க, என் இறைவனும் உங்கள் இறைவனுமாகிய அல்லாஹ்விடம் நான் பாதுகாப்புத் தேடுகிறேன்.) இப்னு அப்பாஸ் (ரழி) அவர்களும், அபூ ஸாலிஹ் அவர்களும், \"இது வாய்மொழித் தாக்குதலையும் அவதூறுகளையும் குறிக்கிறது\" என்று கூறினார்கள். கத்தாதா அவர்கள், \"இதன் பொருள் நேரடியான 'கல்லெறிதல்' என்பதாகும். அதாவது: 'என்னையும் உங்களையும் படைத்த அல்லாஹ்விடம், உங்களின் தீய சொற்களோ அல்லது செயல்களோ என்னை நெருங்காதிருக்க நான் பாதுகாப்புத் தேடுகிறேன்' என்பதாகும்'' என்று கூறினார்கள். ﴾وَإِن لَّمْ تُؤْمِنُواْ لِى فَاعْتَزِلُونِ ﴿\n\r\n\n\r\n\n\r\n(நீங்கள் என்னை நம்பவில்லை என்றால், என்னை விட்டு விலகி விடுங்கள்) என்பதன் பொருள், 'அல்லாஹ் நமக்கிடையே தீர்ப்பளிக்கும் வரை நாம் ஒருவரையொருவர் தொந்தரவு செய்யாமல் விலகி இருப்போம்' என்பதாகும். மூஸா (அலை) அவர்கள் நீண்ட காலம் அவர்களிடையே தங்கியிருந்து, அல்லாஹ்வின் அத்தாட்சிகள் அவர்களுக்கு எதிராக நிலைநாட்டப்பட்ட பின்னரும், அது அவர்களின் நிராகரிப்பையும் பிடிவாதத்தையும் மட்டுமே அதிகரித்தது. எனவே, அவர் அவர்களுக்கு எதிராகத் தனது இறைவனிடம் பிரார்த்தித்தார்கள்; அந்தப் பிரார்த்தனை ஏற்றுக்கொள்ளப்பட்டது. அல்லாஹ் கூறுகிறான்: ﴾وَقَالَ مُوسَى رَبَّنَآ إِنَّكَ ءاتَيْتَ فِرْعَوْنَ وَمَلاّهُ زِينَةً وَأَمْوَالاً فِى الْحَيَوةِ الدُّنْيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَ رَبَّنَا اطْمِسْ عَلَى أَمْوَلِهِمْ وَاشْدُدْ عَلَى قُلُوبِهِمْ فَلاَ يُؤْمِنُواْ حَتَّى يَرَوُاْ الْعَذَابَ الاٌّلِيمَ قَالَ قَدْ أُجِيبَتْ دَّعْوَتُكُمَا فَاسْتَقِيمَا﴿\n\r\n\n\r\n\n\r\n(மேலும் மூஸா கூறினார்கள்: \"எங்கள் இறைவனே! நீ ஃபிர்அவ்னுக்கும் அவனுடைய தலைவர்களுக்கும் இவ்வுலக வாழ்வில் அலங்காரத்தையும் செல்வங்களையும் நிச்சயமாக வழங்கியுள்ளாய். எங்கள் இறைவனே! அவர்கள் உனது பாதையிலிருந்து (மக்களை) வழிதவறச் செய்வதற்காகவே (இவற்றை உபயோகிக்கின்றனர்). எங்கள் இறைவனே! அவர்களின் செல்வங்களை அழித்து, அவர்களின் இதயங்களைக் கடினமாக்கிவிடுவாயாக! துன்புறுத்தும் வேதனையைக் காணும் வரை அவர்கள் ஈமான் கொள்ள மாட்டார்கள்.\" அல்லாஹ் கூறினான்: \"உங்கள் இருவரின் பிரார்த்தனையும் நிச்சயமாக ஏற்கப்பட்டது. எனவே, நீங்கள் இருவரும் நேர்வழியில் உறுதியாக இருங்கள்.\") (10:88-89) மேலும் அல்லாஹ் இங்கே கூறுகிறான்: ﴾فَدَعَا رَبَّهُ أَنَّ هَـؤُلاَءِ قَوْمٌ مُّجْرِمُونَ ﴿\n\r\n\n\r\n\n\r\n(எனவே அவர் (மூஸா) தனது இறைவனிடம், \"நிச்சயமாக இவர்கள் குற்றவாளிகளான மக்கள்\" என்று பிரார்த்தித்தார்கள்.) அதன் பிறகு அல்லாஹ், ஃபிர்அவ்னின் சம்மதமோ அனுமதியோ இன்றி பனூ இஸ்ராயீல் மக்களை அங்கிருந்து வெளியே அழைத்துச் செல்லுமாறு அவருக்குக் கட்டளையிட்டான். அல்லாஹ் கூறினான்: ﴾فَأَسْرِ بِعِبَادِى لَيْلاً إِنَّكُم مُّتَّبَعُونَ ﴿\n\r\n\n\r\n\n\r\n(எனது அடியார்களை அழைத்துக் கொண்டு இரவோடு இரவாகப் புறப்படுங்கள். நிச்சயமாக நீங்கள் பின்தொடரப்படுவீர்கள்.) இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾وَلَقَدْ أَوْحَيْنَآ إِلَى مُوسَى أَنْ أَسْرِ بِعِبَادِى فَاضْرِبْ لَهُمْ طَرِيقاً فِى الْبَحْرِ يَبَساً لاَّ تَخَافُ دَرَكاً وَلاَ تَخْشَى ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக நாம் மூஸா (அலை) அவர்களுக்கு வஹீ (இறைச்செய்தி) அறிவித்தோம்: \"எனது அடியார்களை அழைத்துக் கொண்டு இரவில் பயணம் செய்வீராக! (எதிரிகளால்) பிடிக்கப்படுவோம் என்றோ அல்லது (கடலில் மூழ்கிவிடுவோம் என்றோ) அஞ்சாமல், கடலில் அவர்களுக்காக ஒரு உலர்ந்த பாதையை ஏற்படுத்துவீராக!\") (20:77) ﴾وَاتْرُكِ الْبَحْرَ رَهْواً إِنَّهُمْ جُندٌ مُّغْرَقُونَ ﴿\n\r\n\n\r\n\n\r\n(மேலும் கடலை அது இருந்தவாறே (அமைதியாகவும் பிளவுபட்டும்) விட்டுவிடுவீராக. நிச்சயமாக, அவர்கள் மூழ்கடிக்கப்பட வேண்டிய ஒரு படையினராவர்.) மூஸா (அலை) அவர்களும் பனூ இஸ்ராயீல் மக்களும் கடலைக் கடந்ததும், மூஸா (அலை) அவர்கள் தனது கைத்தடியால் கடலை மீண்டும் அடிக்க விரும்பினார்கள். அவ்வாறு செய்தால் கடல் பழைய நிலைக்குத் திரும்பி, ஃபிர்அவ்ன் தங்களைப் பின்தொடர முடியாதவாறு தடையாக இருக்கும் என்று அவர்கள் கருதினார்கள். ஆனால் அல்லாஹ் அதை அப்படியே அமைதியாகவும் பிளவுபட்டும் விட்டுவிடுமாறு கட்டளையிட்டான். அவர்கள் அனைவரும் மூழ்கடிக்கப்படுவார்கள் என்ற நற்செய்தியை அவருக்கு வழங்கி, ஃபிர்அவ்னால் பிடிக்கப்படுவோம் என்றோ கடலில் மூழ்கிவிடுவோம் என்றோ அஞ்ச வேண்டாம் என்றும் கூறினான். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: ﴾وَاتْرُكِ الْبَحْرَ رَهْواً﴿\n\r\n\n\r\n\n\r\n(மேலும் கடலை அது இருந்தவாறே விட்டுவிடுவீராக.) என்பதன் பொருள், அதை அப்படியே விட்டுவிட்டு தொடர்ந்து முன்னேறிச் செல்லுங்கள் என்பதாகும். முஜாஹித் அவர்கள் கூறினார்கள்: ﴾رَهْواً﴿\n\r\n\n\r\n\n\r\n(இருந்தவாறே) என்பதன் பொருள், உலர்ந்த பாதையாக, அது இருந்த அதே நிலையில் என்பதாகும். 'கடல் மீண்டும் பழைய நிலைக்குத் திரும்பக் கட்டளையிட வேண்டாம்; அவர்களின் இறுதி ஆள் நுழையும் வரை அதை அப்படியே விட்டுவிடுங்கள்.' இக்ரிமா, அர்-ரபீஃ பின் அனஸ், அத்-தஹ்ஹாக், கத்தாதா, இப்னு ஸைத், கஅப் அல்-அஹ்பார், சிமாக் பின் ஹர்ப் மற்றும் பலரும் இதே கருத்தைக் கொண்டிருந்தனர். ﴾كَمْ تَرَكُواْ مِن جَنَّـتٍ وَعُيُونٍ وَزُرُوعٍ﴿\n\r\n\n\r\n\n\r\n(எத்தனை சோலைகளையும் நீரூற்றுகளையும் அவர்கள் விட்டுச் சென்றார்கள்! இன்னும் பசுமையான பயிர்களையும்.) இது ஆறுகளையும் கிணறுகளையும் குறிக்கிறது. ﴾وَمَقَامٍ كَرِيمٍ﴿\n\r\n\n\r\n\n\r\nமேலும் கண்ணியமிக்க இடங்களையும் - இதன் பொருள் சிறந்த இருப்பிடங்கள் மற்றும் அழகான இடங்கள் என்பதாகும். முஜாஹித் அவர்களும் ஸயீத் பின் ஜுபைர் அவர்களும்: ﴾وَمَقَامٍ كَرِيمٍ﴿\n\r\n\n\r\n\n\r\n(கண்ணியமிக்க இடங்கள்) என்பது உயர்ந்த இடங்களைக் குறிக்கும் என்று கூறினார்கள். ﴾وَنَعْمَةٍ كَانُواْ فِيهَا فَـكِهِينَ ﴿\n\r\n\n\r\n\n\r\n(மேலும் அவர்கள் அனுபவித்து வந்த சுகபோகங்களையும்!) என்பதன் பொருள், அவர்கள் அனுபவித்த வாழ்க்கை வசதிகள்; அவர்கள் விரும்பியதைச் சாப்பிடவும், விரும்பியதை உடுத்தவும், செல்வத்தோடும் அதிகாரத்தோடும் அந்த தேசத்தில் வாழ்ந்தார்கள். பின்னர் இவை அனைத்தும் ஒரே காலையில் பறிக்கப்பட்டன. அவர்கள் இவ்வுலகை விட்டு நீங்கி நரகத்திற்குச் சென்றார்கள். அது எவ்வளவு மிக மோசமான தங்குமிடம்! ﴾كَذَلِكَ وَأَوْرَثْنَـهَا قَوْماً ءَاخَرِينَ ﴿\n\r\n\n\r\n\n\r\n(இவ்வாறே நடந்தது! மற்றுமொரு சமூகத்தை அவற்றுக்கு வாரிசாக்கினோம்.) அதாவது பனூ இஸ்ராயீல் மக்களை. ﴾فَمَا بَكَتْ عَلَيْهِمُ السَّمَآءُ وَالاٌّرْضُ﴿\n\r\n\n\r\n\n\r\n(மேலும் அவர்களுக்காக வானமும் பூமியும் அழவில்லை.) அதாவது, வானத்தின் வாயில்கள் வழியாக ஏறிச் செல்லக்கூடிய எந்த நற்செயல்களும் அவர்களிடம் இல்லை. பொதுவாக ஒரு நம்பிக்கையாளர் இறக்கும்போது அவருக்காக வானம் அழும். மேலும், அல்லாஹ்வை வணங்குவதற்காகப் பூமியில் அவர்களுக்கு எந்த இடமும் இருக்கவில்லை. எனவே, அவர்களின் குஃப்ரு (நிராகரிப்பு), பாவம் மற்றும் பிடிவாதத்தின் காரணமாக அவர்களுக்கு எவ்வித அவகாசமும் வழங்கப்படவில்லை. இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ளார்கள்: ஸயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள்: ஒரு மனிதர் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் வந்து, \"ஓ அபூ அப்பாஸ் அவர்களே! ﴾فَمَا بَكَتْ عَلَيْهِمُ السَّمَآءُ وَالاٌّرْضُ وَمَا كَانُواْ مُنظَرِينَ ﴿ (அவர்களுக்காக வானமும் பூமியும் அழவில்லை; அவர்களுக்கு அவகாசமும் அளிக்கப்படவில்லை) என்று அல்லாஹ் கூறுகிறானே, வானமும் பூமியும் யாருக்காகவாவது அழுகின்றனவா?\" என்று கேட்டார். அதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஆம், வானத்தில் ஒவ்வொரு மனிதருக்கும் ஒரு வாயில் உண்டு. அதன் வழியாகவே அவருடைய வாழ்வாதாரம் இறங்குகிறது, அவருடைய நற்செயல்கள் மேலே ஏறிச் செல்கின்றன. ஒரு முஃமின் (நம்பிக்கையாளர்) மரணிக்கும்போது, அந்த வாயில் மூடப்படுகிறது. அது அவரை இழந்து அவருக்காக அழுகிறது. அவ்வாறே அவர் பூமியில் தொழுது அல்லாஹ்வை நினைவு கூர்ந்த இடங்களும் அவருக்காக அழுகின்றன. ஆனால் ஃபிர்அவ்னின் மக்கள் பூமியில் எந்த நற்செயலையும் விட்டுச் செல்லவில்லை, அவர்களின் எந்த நற்செயலும் அல்லாஹ்விடம் ஏறிச் செல்லவில்லை. எனவேதான் வானமும் பூமியும் அவர்களுக்காக அழவில்லை.\" அல்-அவ்ஃபீ அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இவ்வாறே அறிவித்துள்ளார்கள். ﴾وَلَقَدْ نَجَّيْنَا بَنِى إِسْرَءِيلَ مِنَ الْعَذَابِ الْمُهِينِ - مِن فِرْعَوْنَ إِنَّهُ كَانَ عَالِياً مِّنَ الْمُسْرِفِينَ ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக நாம் பனூ இஸ்ராயீல் மக்களை இழிவுபடுத்தும் வேதனையிலிருந்து காப்பாற்றினோம் - ஃபிர்அவ்னிடமிருந்து; நிச்சயமாக அவன் வரம்பு மீறியவர்களில் ஒருவனாகவும் ஆணவம் கொண்டவனாகவும் இருந்தான்.) ஃபிர்அவ்னின் பிடியில் அவர்கள் சிக்கித் தவித்தபோது, கடினமான வேலைகளைச் செய்யக் கட்டாயப்படுத்தப்பட்ட இழிவிலிருந்தும் அடிமைத்தனத்திலிருந்தும் அல்லாஹ் அவர்களை எப்படிக் காப்பாற்றினான் என்பதை இங்கே நினைவூட்டுகிறான். ﴾مِن فِرْعَوْنَ إِنَّهُ كَانَ عَالِياً﴿\n\r\n\n\r\n\n\r\n(ஃபிர்அவ்னிடமிருந்து; நிச்சயமாக அவன் ஆணவம் கொண்டவனாக இருந்தான்.) அதாவது, அவன் பெருமையும் பிடிவாதமும் கொண்டவனாக இருந்தான். இது பின்வரும் வசனத்தைப் போன்றது: ﴾إِنَّ فِرْعَوْنَ عَلاَ فِى الاٌّرْضِ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக, ஃபிர்அவ்ன் பூமியில் தன்னை உயர்த்திக் கொண்டான்.) (28:4). ﴾فَاسْتَكْبَرُواْ وَكَانُواْ قَوْماً عَـلِينَ﴿\n\r\n\n\r\n\n\r\n(ஆனால் அவர்கள் பெருமையடித்தார்கள்; அவர்கள் தங்களை உயர்த்திக் கொள்ளும் மக்களாக இருந்தார்கள்.) (23:46). அவன் வரம்பு மீறியவனாகவும், தன்னைப் பற்றி மிகையான தற்பெருமை கொண்டவனாகவும் இருந்தான். ﴾وَلَقَدِ اخْتَرْنَـهُمْ عَلَى عِلْمٍ عَلَى الْعَـلَمِينَ ﴿\n\r\n\n\r\n\n\r\n(மேலும் நாம் அறிந்து கொண்டே அவர்களை அக்கால உலகத்தாரை விட மேலாகத் தேர்ந்தெடுத்தோம்.) \"அவர்கள் வாழ்ந்த காலத்தில் இருந்த மற்ற மக்களை விட அவர்கள் தேர்ந்தெடுக்கப்பட்டார்கள்\" என்று முஜாஹித் அவர்கள் கூறினார்கள். கத்தாதா அவர்கள் கூறுகையில், \"அவர்கள் தங்கள் காலத்து மக்களை விடத் தேர்ந்தெடுக்கப்பட்டனர். ஒவ்வொரு காலக்கட்டத்திலும் மற்றவர்களை விடச் சிறந்த மக்கள் தேர்ந்தெடுக்கப்படுகின்றனர்\" என்றார். இது பின்வரும் வசனத்தைப் போன்றது: ﴾قَالَ يَمُوسَى إِنْى اصْطَفَيْتُكَ عَلَى النَّاسِ﴿\n\r\n\n\r\n\n\r\n(அல்லாஹ் கூறினான்: \"மூஸாவே! நான் உன்னை மக்களில் தேர்ந்தெடுத்துள்ளேன்.\") (7:144). அதாவது அவரது காலத்து மக்களை விட. இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَاصْطَفَـكِ عَلَى نِسَآءِ الْعَـلَمِينَ﴿\n\r\n\n\r\n\n\r\n(மேலும் (அல்லாஹ்) உன்னை (மர்யம்) அகிலத்துப் பெண்களை விடத் தேர்ந்தெடுத்திருக்கிறான்.) (3:42). அதாவது, மர்யம் (அலை) அவர்கள் தனது காலத்துப் பெண்களை விடத் தேர்ந்தெடுக்கப்பட்டார்கள். கதீஜா (ரழி) அவர்கள் மர்யம் (அலை) அவர்களுக்கு இணையானவர்கள் அல்லது அவர்களை விட அந்தஸ்தில் உயர்ந்தவர்கள். ஃபிர்அவ்னின் மனைவியான ஆசியா பின்த் முஸாஹிம் (ரழி) அவர்களும் அவ்வாறே. மேலும், மற்ற அனைத்துப் பெண்களையும் விட ஆயிஷா (ரழி) அவர்களின் சிறப்பானது, மற்ற எல்லா உணவுகளையும் விட 'தரீத்' (Tharid) எனும் உணவின் சிறப்பைப் போன்றதாகும். ﴾وَءَاتَيْنَـهُم مِّنَ الاٌّيَـتِ﴿\n\r\n\n\r\n\n\r\n(மேலும் அவர்களுக்கு அத்தாட்சிகளை வழங்கினோம்) என்பதன் பொருள் தெளிவான ஆதாரங்கள் மற்றும் அசாத்தியமான சான்றுகள் என்பதாகும். ﴾مَا فِيهِ بَلَؤٌاْ مُّبِينٌ﴿\n\r\n\n\r\n\n\r\n(அதில் தெளிவானதொரு சோதனை இருந்தது) என்பதன் பொருள், அதன் மூலம் யார் நேர்வழி பெறுகிறார்கள் என்பதைக் கண்டறிய வைக்கப்பட்ட பகிரங்கமான சோதனை என்பதாகும்."},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=37\" class=\"link\">44:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:37 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=37\" class=\"link\">44:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:37 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=37\" class=\"link\">44:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:37 ஐ பார்க்கவும்"},"37":{"html":"<strong>உயிர்த்தெழுதலை மறுப்பவர்களுக்கு மறுப்பு</strong><br />\r\n<br />\r\nஇணைவைப்பாளர்கள் உயிர்த்தெழுதலை மறுப்பதையும், மரணத்திற்குப் பிறகு வாழ்வோ அல்லது மீள எழுப்பப்படுவதோ இல்லை என்றும், இந்த வாழ்க்கைக்குப் பிறகு வேறொன்றும் இல்லை என்றும் அவர்கள் கொண்டிருந்த நம்பிக்கையையும் அல்லாஹ் இங்கே கண்டிக்கிறான். தங்கள் முன்னோர்கள் இறந்துவிட்டார்கள், அவர்கள் மீண்டும் திரும்பி வரவில்லை என்பதை இதற்கு அவர்கள் ஒரு காரணமாகக் காட்டினார்கள். \"உயிர்த்தெழுதல் என்பது உண்மையானால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْتُواْ</span> <span class=\"quran-arabic-font text-success\">بِآبَائِنَا</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">صَادِقِينَ</span><br />\r\n<br />\r\n(நீங்கள் உண்மையாளர்களாக இருந்தால், எங்களது முன்னோர்களைத் திரும்பக் கொண்டு வாருங்கள்!)\" என்று அவர்கள் கூறினார்கள். இது ஒரு தவறான ஆதாரமும் போலியான வாதமுமாகும். ஏனெனில், உயிர்த்தெழுதல் என்பது நியாயத்தீர்ப்பு நாளில்தான் நிகழுமே தவிர, இந்த உலகில் அல்ல; இந்த உலகம் முடிவுக்கு வந்து அழிந்த பின்னரே அது நிகழும். அல்லாஹ் அனைத்துப் படைப்புகளையும் மீண்டும் உயிர்ப்பித்து, புதிதாகப் படைத்துக் கொண்டு வருவான். அவன் தீயவர்களை நரக நெருப்பிற்கு எரிபொருளாக ஆக்குவான். பின்னர், உயிர்த்தெழுதலை மறுத்து, தவிர்க்க முடியாத வேதனையை அனுபவித்த ஏனைய இணைவைப்பாளர்களைக் குறிப்பிட்டு அல்லாஹ் இவர்களை அச்சுறுத்தி எச்சரிக்கிறான்.<br />\r\n<br />\r\nதுப்பஃ (Tubba`) சமூகத்தினர், அதாவது ஸபா (Saba') தேசத்தவர் போன்றோரை அல்லாஹ் அழித்து, அவர்களது தேசத்தைப் பாழாக்கி, அவர்களைப் பூமி எங்கும் சிதறடித்தான்; இதை நாம் ஏற்கனவே ஸூரா ஸபாவில் பார்த்துள்ளோம். அந்த இணைவைப்பாளர்கள் உயிர்த்தெழுதலை மறுத்ததாலேயே இந்நிலை அவர்களுக்கு ஏற்பட்டது. இங்கும், மக்காவிலுள்ள இணைவைப்பாளர்கள் அவர்களுடன் ஒப்பிடப்படுகிறார்கள். இவர்கள் (குறைஷிகள்) அத்னான் (Adnan) வழியில் வந்த அரபிகளாக இருப்பது போலவே, அந்த துப்பஃ சமூகத்தினரும் கஹ்தான் (Qahtan) வழியில் வந்த அரபு வம்சாவளியினரே ஆவர். ஸபா என்று அழைக்கப்படும் ஹிம்யர் (Himyar) மக்களிடையே, ஒருவர் மன்னராகும் போது அவர்கள் அவரை 'துப்பஃ' என்று அழைப்பார்கள். இது பாரசீக மன்னருக்கு 'குஸ்ரூ' (Chosroes), ரோமானிய மன்னருக்கு 'சீசர்' (Caesar), எகிப்தின் நிராகரிக்கும் ஆட்சியாளருக்கு 'ஃபிர்அவ்ன்' (Fir'awn), எத்தியோப்பிய மன்னருக்கு 'நஜ்ஜாஷி' (Negus) என்று பட்டப்பெயர்கள் வழங்கப்பட்டது போன்றதாகும். ஆனால், துப்பஃ மன்னர்களில் ஒருவர் யமனிலிருந்து புறப்பட்டு, சமர்கந்த் (Samarqand) வரை தனது பேரரசை விரிவாக்கம் செய்து வெற்றிப் பயணங்களை மேற்கொண்டார். அவர்தான் 'அல்-ஹீரா' (Al-Hirah) நகரத்தை நிறுவியவர். அவர் ஜாஹிலிய்யா காலத்தில் மதீனா வழியாகச் சென்றார் என்பது ஒருமித்த கருத்தாகும். அவர் மதீனாவாசிகளுடன் போரிட்டபோது, அவர்கள் அவரை எதிர்த்தனர்; பகலில் அவர்கள் அவருடன் போரிடுவார்கள், ஆனால் இரவில் அவருக்கு உணவு வழங்குவார்கள். இதனால் அவர் அவர்கள் முன் வெட்கமடைந்து, அவர்களுக்குத் தீங்கு செய்வதைக் கைவிட்டார். அவருடன் இரண்டு யூத ரப்பிகள் (Rabbis) இருந்தனர். அவர்கள் அம்மன்னரிடம், இந்த நகரத்தை உம்மால் ஒருபோதும் வெற்றி கொள்ள முடியாது என்றும், ஏனெனில் இது இறுதிக்காலத்தில் ஒரு நபி புலம்பெயர்ந்து (ஹிஜ்ரத் செய்து) வரவிருக்கும் இடம் என்றும் கூறினார்கள். எனவே அவர் பின்வாங்கி, அந்த இரண்டு ரப்பிகளையும் தன்னுடன் யமனுக்கு அழைத்துச் சென்றார்.<br />\r\n<br />\r\nஅவர் மக்கா வழியாகச் சென்றபோது, கஃபாவை இடிக்க விரும்பினார். ஆனால் அப்போதும் அந்த ரப்பிகள் அவ்வாறு செய்ய வேண்டாமென அவரிடம் கூறினர். இப்ராஹீம் அல்-கலீல் (அலை) அவர்களால் கட்டப்பட்ட இந்த ஆலயத்தின் மகத்துவத்தையும், இறுதிக்காலத்தில் அனுப்பப்படவிருக்கும் அந்த நபியின் மூலம் இது பெரும் சிறப்பைப் பெறும் என்பதையும் அவர்கள் அவருக்கு விளக்கினர். எனவே, அவர் அதை மதித்து, அதைத் தவாஃப் செய்ததுடன், அதற்கு உயர்தரமான உறையையும் (கிஸ்வா) அணிவித்தார். பின்னர் அவர் யமனுக்குத் திரும்பி, நேர்வழியின் மார்க்கத்தைப் பின்பற்றுமாறு தன் மக்களுக்கு அழைப்பு விடுத்தார். அந்த நேரத்தில், மஸீஹ் (ஈஸா) (அலை) அவர்களின் வருகைக்கு முன்பாக, நேர்வழி பெற்றவர்கள் பின்பற்றிய மார்க்கமாக மூஸா (அலை) அவர்களின் மார்க்கமே இருந்தது. எனவே யமன் மக்கள் அவருடன் சேர்ந்து அந்த நேர்வழியின் மார்க்கத்தை ஏற்றுக்கொண்டனர். அப்துர் ரஸ்ஸாக் பதிவு செய்துள்ள ஒரு அறிவிப்பில், அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَدْرِي</span> <span class=\"quran-arabic-font text-success\">تُبَّعٌ</span> <span class=\"quran-arabic-font text-success\">نَبِيًّا</span> <span class=\"quran-arabic-font text-success\">كَانَ،</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">نَبِي</span>»<br />\r\n<br />\r\n(துப்பஃ ஒரு நபியா அல்லது இல்லையா என்பது எனக்குத் தெரியாது).\" துலைம் பின் அப்துர் ரஹ்மான் அறிவிப்பதாவது: \"அதஃ பின் அபீ ரபாஹ் அவர்கள் கூறினார்கள்: 'துப்பஃவை ஏசாதீர்கள், ஏனெனில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை ஏசுவதைத் தடுத்துள்ளார்கள்' ஏனெனில் அவர் இஸ்லாத்தை ஏற்றிருந்தார்.\" அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"உயிர்த்தெழுதலை மறுப்பவர்களுக்கு மறுப்பு\n\r\n\n\r\nஇணைவைப்பாளர்கள் உயிர்த்தெழுதலை மறுப்பதையும், மரணத்திற்குப் பிறகு வாழ்வோ அல்லது மீள எழுப்பப்படுவதோ இல்லை என்றும், இந்த வாழ்க்கைக்குப் பிறகு வேறொன்றும் இல்லை என்றும் அவர்கள் கொண்டிருந்த நம்பிக்கையையும் அல்லாஹ் இங்கே கண்டிக்கிறான். தங்கள் முன்னோர்கள் இறந்துவிட்டார்கள், அவர்கள் மீண்டும் திரும்பி வரவில்லை என்பதை இதற்கு அவர்கள் ஒரு காரணமாகக் காட்டினார்கள். \"உயிர்த்தெழுதல் என்பது உண்மையானால்,\n\r\n\n\r\nفَأْتُواْ بِآبَائِنَا إِن كُنتُمْ صَادِقِينَ\n\r\n\n\r\n(நீங்கள் உண்மையாளர்களாக இருந்தால், எங்களது முன்னோர்களைத் திரும்பக் கொண்டு வாருங்கள்!)\" என்று அவர்கள் கூறினார்கள். இது ஒரு தவறான ஆதாரமும் போலியான வாதமுமாகும். ஏனெனில், உயிர்த்தெழுதல் என்பது நியாயத்தீர்ப்பு நாளில்தான் நிகழுமே தவிர, இந்த உலகில் அல்ல; இந்த உலகம் முடிவுக்கு வந்து அழிந்த பின்னரே அது நிகழும். அல்லாஹ் அனைத்துப் படைப்புகளையும் மீண்டும் உயிர்ப்பித்து, புதிதாகப் படைத்துக் கொண்டு வருவான். அவன் தீயவர்களை நரக நெருப்பிற்கு எரிபொருளாக ஆக்குவான். பின்னர், உயிர்த்தெழுதலை மறுத்து, தவிர்க்க முடியாத வேதனையை அனுபவித்த ஏனைய இணைவைப்பாளர்களைக் குறிப்பிட்டு அல்லாஹ் இவர்களை அச்சுறுத்தி எச்சரிக்கிறான்.\n\r\n\n\r\nதுப்பஃ (Tubba`) சமூகத்தினர், அதாவது ஸபா (Saba') தேசத்தவர் போன்றோரை அல்லாஹ் அழித்து, அவர்களது தேசத்தைப் பாழாக்கி, அவர்களைப் பூமி எங்கும் சிதறடித்தான்; இதை நாம் ஏற்கனவே ஸூரா ஸபாவில் பார்த்துள்ளோம். அந்த இணைவைப்பாளர்கள் உயிர்த்தெழுதலை மறுத்ததாலேயே இந்நிலை அவர்களுக்கு ஏற்பட்டது. இங்கும், மக்காவிலுள்ள இணைவைப்பாளர்கள் அவர்களுடன் ஒப்பிடப்படுகிறார்கள். இவர்கள் (குறைஷிகள்) அத்னான் (Adnan) வழியில் வந்த அரபிகளாக இருப்பது போலவே, அந்த துப்பஃ சமூகத்தினரும் கஹ்தான் (Qahtan) வழியில் வந்த அரபு வம்சாவளியினரே ஆவர். ஸபா என்று அழைக்கப்படும் ஹிம்யர் (Himyar) மக்களிடையே, ஒருவர் மன்னராகும் போது அவர்கள் அவரை 'துப்பஃ' என்று அழைப்பார்கள். இது பாரசீக மன்னருக்கு 'குஸ்ரூ' (Chosroes), ரோமானிய மன்னருக்கு 'சீசர்' (Caesar), எகிப்தின் நிராகரிக்கும் ஆட்சியாளருக்கு 'ஃபிர்அவ்ன்' (Fir'awn), எத்தியோப்பிய மன்னருக்கு 'நஜ்ஜாஷி' (Negus) என்று பட்டப்பெயர்கள் வழங்கப்பட்டது போன்றதாகும். ஆனால், துப்பஃ மன்னர்களில் ஒருவர் யமனிலிருந்து புறப்பட்டு, சமர்கந்த் (Samarqand) வரை தனது பேரரசை விரிவாக்கம் செய்து வெற்றிப் பயணங்களை மேற்கொண்டார். அவர்தான் 'அல்-ஹீரா' (Al-Hirah) நகரத்தை நிறுவியவர். அவர் ஜாஹிலிய்யா காலத்தில் மதீனா வழியாகச் சென்றார் என்பது ஒருமித்த கருத்தாகும். அவர் மதீனாவாசிகளுடன் போரிட்டபோது, அவர்கள் அவரை எதிர்த்தனர்; பகலில் அவர்கள் அவருடன் போரிடுவார்கள், ஆனால் இரவில் அவருக்கு உணவு வழங்குவார்கள். இதனால் அவர் அவர்கள் முன் வெட்கமடைந்து, அவர்களுக்குத் தீங்கு செய்வதைக் கைவிட்டார். அவருடன் இரண்டு யூத ரப்பிகள் (Rabbis) இருந்தனர். அவர்கள் அம்மன்னரிடம், இந்த நகரத்தை உம்மால் ஒருபோதும் வெற்றி கொள்ள முடியாது என்றும், ஏனெனில் இது இறுதிக்காலத்தில் ஒரு நபி புலம்பெயர்ந்து (ஹிஜ்ரத் செய்து) வரவிருக்கும் இடம் என்றும் கூறினார்கள். எனவே அவர் பின்வாங்கி, அந்த இரண்டு ரப்பிகளையும் தன்னுடன் யமனுக்கு அழைத்துச் சென்றார்.\n\r\n\n\r\nஅவர் மக்கா வழியாகச் சென்றபோது, கஃபாவை இடிக்க விரும்பினார். ஆனால் அப்போதும் அந்த ரப்பிகள் அவ்வாறு செய்ய வேண்டாமென அவரிடம் கூறினர். இப்ராஹீம் அல்-கலீல் (அலை) அவர்களால் கட்டப்பட்ட இந்த ஆலயத்தின் மகத்துவத்தையும், இறுதிக்காலத்தில் அனுப்பப்படவிருக்கும் அந்த நபியின் மூலம் இது பெரும் சிறப்பைப் பெறும் என்பதையும் அவர்கள் அவருக்கு விளக்கினர். எனவே, அவர் அதை மதித்து, அதைத் தவாஃப் செய்ததுடன், அதற்கு உயர்தரமான உறையையும் (கிஸ்வா) அணிவித்தார். பின்னர் அவர் யமனுக்குத் திரும்பி, நேர்வழியின் மார்க்கத்தைப் பின்பற்றுமாறு தன் மக்களுக்கு அழைப்பு விடுத்தார். அந்த நேரத்தில், மஸீஹ் (ஈஸா) (அலை) அவர்களின் வருகைக்கு முன்பாக, நேர்வழி பெற்றவர்கள் பின்பற்றிய மார்க்கமாக மூஸா (அலை) அவர்களின் மார்க்கமே இருந்தது. எனவே யமன் மக்கள் அவருடன் சேர்ந்து அந்த நேர்வழியின் மார்க்கத்தை ஏற்றுக்கொண்டனர். அப்துர் ரஸ்ஸாக் பதிவு செய்துள்ள ஒரு அறிவிப்பில், அபூ ஹுரைரா (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا أَدْرِي تُبَّعٌ نَبِيًّا كَانَ، أَمْ غَيْرَ نَبِي»\n\r\n\n\r\n(துப்பஃ ஒரு நபியா அல்லது இல்லையா என்பது எனக்குத் தெரியாது).\" துலைம் பின் அப்துர் ரஹ்மான் அறிவிப்பதாவது: \"அதஃ பின் அபீ ரபாஹ் அவர்கள் கூறினார்கள்: 'துப்பஃவை ஏசாதீர்கள், ஏனெனில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரை ஏசுவதைத் தடுத்துள்ளார்கள்' ஏனெனில் அவர் இஸ்லாத்தை ஏற்றிருந்தார்.\" அல்லாஹ்வே மிக அறிந்தவன்."},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=42\" class=\"link\">44:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:42 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=42\" class=\"link\">44:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:42 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=42\" class=\"link\">44:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:42 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=42\" class=\"link\">44:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:42 ஐ பார்க்கவும்"},"42":{"html":"<strong>இந்த உலகம் ஒரு மகா ஞானத்திற்காகவே படைக்கப்பட்டது</strong><br />\r\n<br />\r\nஇங்கு அல்லாஹ் தனது நீதியைப் பற்றியும், தான் விளையாட்டு, வீண் மற்றும் பொய் ஆகியவற்றை விட்டும் மிகவும் உயர்ந்தவன் என்றும் நமக்குக் கூறுகிறான். இது இந்த வசனத்தைப் போன்றதாகும்:<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">بَاطِلاً</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">ظَنُّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">فَوَيْلٌ</span> <span class=\"quran-arabic-font text-success\">لِّلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(வானத்தையும், பூமியையும், அவற்றுக்கு இடையே உள்ளவற்றையும் நாம் வீணுக்காகப் படைக்கவில்லை! இது நிராகரிப்பவர்களின் எண்ணமாகும்! ஆகவே, நிராகரிப்பவர்களுக்கு நரக நெருப்பினால் கேடுதான் உண்டு!) (<a href=\"qurandisp.php?sura=38&ayah=27\" class=\"link\">38:27</a>)<span class=\"quran-arabic-font text-success\">﴾أَفَحَسِبْتُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّمَا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">عَبَثاً</span> <span class=\"quran-arabic-font text-success\">وَأَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُرْجَعُونَ</span> - <span class=\"quran-arabic-font text-success\">فَتَعَالَى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَٰهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நாம் உங்களை வீணாகப் படைத்தோம் என்றும், நீங்கள் நம்மிடம் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள் என்றும் எண்ணிக் கொண்டீர்களா? உண்மையான அரசனாகிய அல்லாஹ் மிகவும் உயர்ந்தவன். அவனைத் தவிர வேறு இறைவனில்லை; அவன் கண்ணியமிக்க அர்ஷின் அதிபதி ஆவான்!) (<a href=\"qurandisp.php?sura=23&ayah=115\" class=\"link\">23:115</a>-116) பின்னர் அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْفَصْلِ</span> <span class=\"quran-arabic-font text-success\">مِيقَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, தீர்ப்பு நாள் அவர்கள் அனைவருக்கும் (நிர்ணயிக்கப்பட்ட) நேரமாகும்.) இது மறுமை நாளாகும். அந்நாளில் அல்லாஹ் அனைத்துப் படைப்பினங்களுக்கும் இடையில் தீர்ப்பளிப்பான்; அவன் நிராகரிப்பாளர்களைத் தண்டிப்பான் மற்றும் நம்பிக்கையாளர்களுக்கு நற்கூலி வழங்குவான்.<span class=\"quran-arabic-font text-success\">﴾مِيقَاتُهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ﴿</span><br />\r\n<br />\r\n(அவர்கள் அனைவருக்கும் நிர்ணயிக்கப்பட்ட நேரமாகும்) என்பதன் பொருள், அவன் முந்தியவர்கள் மற்றும் பிந்தியவர்கள் என அவர்கள் அனைவரையும் ஒன்று திரட்டுவான் என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُغْنِى</span> <span class=\"quran-arabic-font text-success\">مَوْلًى</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">مَّوْلًى</span> <span class=\"quran-arabic-font text-success\">شَيْئاً﴿</span><br />\r\n<br />\r\n(ஒரு நெருங்கிய உறவினர் மற்றொரு நெருங்கிய உறவினருக்கு எந்தப் பயனும் அளிக்க முடியாத நாள்) என்பதன் பொருள், எந்தவொரு உறவினரும் மற்றொரு உறவினருக்கு உதவ முடியாது என்பதாகும். இது இந்த வசனத்தைப் போன்றதாகும்:<span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">نُفِخَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الصُّورِ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">أَنسَابَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتَسَآءَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பின்னர், எக்காளம் (சூர்) ஊதப்படும் போது, அந்நாளில் அவர்களுக்கு இடையே எந்த உறவுகளும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=23&ayah=101\" class=\"link\">23:101</a>)<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَسْأَلُ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَمِيماً</span> <span class=\"quran-arabic-font text-success\">يُبَصَّرُونَهُمْ﴿</span><br />\r\n<br />\r\n(எந்த நண்பனும் தனது நண்பனைப் பற்றி (அவனது நிலை குறித்து) விசாரிக்க மாட்டான். அவர்கள் ஒருவரையொருவர் பார்க்கும்படி செய்யப்பட்டாலும் சரி) (<a href=\"qurandisp.php?sura=70&ayah=10\" class=\"link\">70:10</a>-11). இதன் பொருள் என்னவென்றால், ஒருவன் தன் சகோதரனைத் தனது கண்களால் பார்த்தாலும் கூட, அவன் எப்படி இருக்கிறான் என்று அவனிடம் விசாரிக்க மாட்டான்.<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ﴿</span><br />\r\n<br />\r\n(அவர்களுக்கு எந்த உதவியும் செய்யப்பட மாட்டாது) என்பதன் பொருள், எந்த உறவினரும் மற்றொருவருக்கு உதவ மாட்டார், மேலும் வெளியிலிருந்தும் அவருக்கு எந்த உதவியும் கிடைக்காது என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">رَّحِمَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் யாருக்குக் கருணை புரிந்தானோ அவரைத் தவிர) என்பதன் பொருள், அந்நாளில் அல்லாஹ் தனது படைப்புகளின் மீது காட்டும் கருணையைத் தவிர வேறு எதுவும் எவருக்கும் பயனளிக்காது என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் மிகைத்தவனும், மகா கருணையாளனும் ஆவான்) என்பதன் பொருள், அவன் அளப்பரிய கருணையுடன் கூடிய வல்லமை மிக்கவன் என்பதாகும்.<br />\r\n<br />","text":"இந்த உலகம் ஒரு மகா ஞானத்திற்காகவே படைக்கப்பட்டது\n\r\n\n\r\nஇங்கு அல்லாஹ் தனது நீதியைப் பற்றியும், தான் விளையாட்டு, வீண் மற்றும் பொய் ஆகியவற்றை விட்டும் மிகவும் உயர்ந்தவன் என்றும் நமக்குக் கூறுகிறான். இது இந்த வசனத்தைப் போன்றதாகும்:﴾وَمَا خَلَقْنَا السَّمَآءَ وَالأَرْضَ وَمَا بَيْنَهُمَا بَاطِلاً ذَلِكَ ظَنُّ الَّذِينَ كَفَرُواْ فَوَيْلٌ لِّلَّذِينَ كَفَرُواْ مِنَ النَّارِ ﴿\n\r\n\n\r\n(வானத்தையும், பூமியையும், அவற்றுக்கு இடையே உள்ளவற்றையும் நாம் வீணுக்காகப் படைக்கவில்லை! இது நிராகரிப்பவர்களின் எண்ணமாகும்! ஆகவே, நிராகரிப்பவர்களுக்கு நரக நெருப்பினால் கேடுதான் உண்டு!) (38:27)﴾أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثاً وَأَنَّكُمْ إِلَيْنَا لاَ تُرْجَعُونَ - فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لاَ إِلَٰهَ إِلاَّ هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ ﴿\n\r\n\n\r\n(நாம் உங்களை வீணாகப் படைத்தோம் என்றும், நீங்கள் நம்மிடம் திரும்பக் கொண்டுவரப்பட மாட்டீர்கள் என்றும் எண்ணிக் கொண்டீர்களா? உண்மையான அரசனாகிய அல்லாஹ் மிகவும் உயர்ந்தவன். அவனைத் தவிர வேறு இறைவனில்லை; அவன் கண்ணியமிக்க அர்ஷின் அதிபதி ஆவான்!) (23:115-116) பின்னர் அல்லாஹ் கூறுகிறான்:﴾إِنَّ يَوْمَ الْفَصْلِ مِيقَاتُهُمْ أَجْمَعِينَ ﴿\n\r\n\n\r\n(நிச்சயமாக, தீர்ப்பு நாள் அவர்கள் அனைவருக்கும் (நிர்ணயிக்கப்பட்ட) நேரமாகும்.) இது மறுமை நாளாகும். அந்நாளில் அல்லாஹ் அனைத்துப் படைப்பினங்களுக்கும் இடையில் தீர்ப்பளிப்பான்; அவன் நிராகரிப்பாளர்களைத் தண்டிப்பான் மற்றும் நம்பிக்கையாளர்களுக்கு நற்கூலி வழங்குவான்.﴾مِيقَاتُهُمْ أَجْمَعِينَ﴿\n\r\n\n\r\n(அவர்கள் அனைவருக்கும் நிர்ணயிக்கப்பட்ட நேரமாகும்) என்பதன் பொருள், அவன் முந்தியவர்கள் மற்றும் பிந்தியவர்கள் என அவர்கள் அனைவரையும் ஒன்று திரட்டுவான் என்பதாகும்.﴾يَوْمَ لاَ يُغْنِى مَوْلًى عَن مَّوْلًى شَيْئاً﴿\n\r\n\n\r\n(ஒரு நெருங்கிய உறவினர் மற்றொரு நெருங்கிய உறவினருக்கு எந்தப் பயனும் அளிக்க முடியாத நாள்) என்பதன் பொருள், எந்தவொரு உறவினரும் மற்றொரு உறவினருக்கு உதவ முடியாது என்பதாகும். இது இந்த வசனத்தைப் போன்றதாகும்:﴾فَإِذَا نُفِخَ فِى الصُّورِ فَلاَ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلاَ يَتَسَآءَلُونَ ﴿\n\r\n\n\r\n(பின்னர், எக்காளம் (சூர்) ஊதப்படும் போது, அந்நாளில் அவர்களுக்கு இடையே எந்த உறவுகளும் இருக்காது; ஒருவரையொருவர் விசாரித்துக் கொள்ளவும் மாட்டார்கள்.) (23:101)﴾وَلاَ يَسْأَلُ حَمِيمٌ حَمِيماً يُبَصَّرُونَهُمْ﴿\n\r\n\n\r\n(எந்த நண்பனும் தனது நண்பனைப் பற்றி (அவனது நிலை குறித்து) விசாரிக்க மாட்டான். அவர்கள் ஒருவரையொருவர் பார்க்கும்படி செய்யப்பட்டாலும் சரி) (70:10-11). இதன் பொருள் என்னவென்றால், ஒருவன் தன் சகோதரனைத் தனது கண்களால் பார்த்தாலும் கூட, அவன் எப்படி இருக்கிறான் என்று அவனிடம் விசாரிக்க மாட்டான்.﴾وَلاَ هُمْ يُنصَرُونَ﴿\n\r\n\n\r\n(அவர்களுக்கு எந்த உதவியும் செய்யப்பட மாட்டாது) என்பதன் பொருள், எந்த உறவினரும் மற்றொருவருக்கு உதவ மாட்டார், மேலும் வெளியிலிருந்தும் அவருக்கு எந்த உதவியும் கிடைக்காது என்பதாகும்.﴾إِلاَّ مَن رَّحِمَ اللَّهُ﴿\n\r\n\n\r\n(அல்லாஹ் யாருக்குக் கருணை புரிந்தானோ அவரைத் தவிர) என்பதன் பொருள், அந்நாளில் அல்லாஹ் தனது படைப்புகளின் மீது காட்டும் கருணையைத் தவிர வேறு எதுவும் எவருக்கும் பயனளிக்காது என்பதாகும்.﴾إِنَّهُ هُوَ الْعَزِيزُ الرَّحِيمُ﴿\n\r\n\n\r\n(நிச்சயமாக அவன் மிகைத்தவனும், மகா கருணையாளனும் ஆவான்) என்பதன் பொருள், அவன் அளப்பரிய கருணையுடன் கூடிய வல்லமை மிக்கவன் என்பதாகும்."},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=50\" class=\"link\">44:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:50 ஐ பார்க்கவும்"},"50":{"html":"<strong>1. மறுமை நாளில் இணைவைப்பவர்களின் நிலையும் அவர்களுக்கான தண்டனையும்</strong><br />\r\n<br />\r\nதன்னைச் சந்திப்பதை மறுக்கும் நிராகரிப்பாளர்களைத் தான் எவ்வாறு தண்டிப்பான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةَ</span> <span class=\"quran-arabic-font text-success\">الزَّقُّومِ</span> - <span class=\"quran-arabic-font text-success\">طَعَامُ</span> <span class=\"quran-arabic-font text-success\">الْأَثِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, ஸக்கூம் மரம் பாவிகளின் உணவாக இருக்கும்.) அதாவது, சொல்லாலும் செயலாலும் பாவம் செய்தவர்கள்; இவர்களே அந்த நிராகரிப்பாளர்கள். இது அபூ ஜஹ்லைக் குறிக்கிறது என்று ஒன்றுக்கும் மேற்பட்ட விரிவுரையாளர்கள் கூறியுள்ளனர். சந்தேகமின்றி, இந்த வசனத்தில் குறிப்பிடப்பட்டவர்களில் அவரும் அடங்குவார்; ஆனால், இது அவரை மட்டும் குறிப்பானது அல்ல. இப்னு ஜரீர் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ அத்-தர்தா (ரழி) அவர்கள் ஒரு மனிதருக்கு ஓதிக் காட்டிக் கொண்டிருந்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةَ</span> <span class=\"quran-arabic-font text-success\">الزَّقُّومِ</span> - <span class=\"quran-arabic-font text-success\">طَعَامُ</span> <span class=\"quran-arabic-font text-success\">الْأَثِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, ஸக்கூம் மரம் பாவிகளின் உணவாக இருக்கும்.) அந்த மனிதர், \"(அநாதையின்) உணவு\" என்று ஓதினார். அதற்கு அபூ அத்-தர்தா (ரழி) அவர்கள், \"ஸக்கூம் மரம் தீயவனின் (ஃபாஜிர்) உணவு என்று சொல்\" என்றார்கள். அதாவது, அவனுக்கு அதைத் தவிர வேறு எந்த உணவும் இருக்காது. முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அதிலிருந்து ஒரு துளி பூமியில் விழுந்தால், அது பூமியில் வாழும் அனைத்து மக்களின் வாழ்வாதாரத்தையும் சீரழித்துவிடும்.\" இது போன்ற ஒரு மர்ஃபூஃ (நபிமொழி) அறிவிப்பு முன்னரே விவரிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَالْمُهْلِ﴿</span><br />\r\n<br />\r\n(கொதிக்கும் எண்ணெயைப் போல,) அதாவது, எண்ணெயின் கசடைப் போல இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَالْمُهْلِ</span> <span class=\"quran-arabic-font text-success\">يَغْلِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْبُطُونِ</span> - <span class=\"quran-arabic-font text-success\">كَغَلْيِ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அது வயிறுகளில் கொதிக்கும், சுடுநீர் கொதிப்பதைப் போல.) அதாவது, அதன் அதீத வெப்பம் மற்றும் துர்நாற்றத்தின் காரணமாக அவ்வாறு இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خُذُوهُ﴿</span><br />\r\n<br />\r\n(அவனைப் பிடியுங்கள்) என்பது நிராகரிப்பாளரைக் குறிக்கிறது. நரகத்தின் காவலர்களிடம் \"அவனைப் பிடியுங்கள்\" என்று அல்லாஹ் கூறும்போது, அவர்களில் எழுபதாயிரம் பேர் அவனைப் பிடிக்க விரைந்து வருவார்கள் என்று அறிவிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاعْتِلُوهُ﴿</span><br />\r\n<br />\r\n(இழுத்துச் செல்லுங்கள்) அதாவது, அவனை இழுத்து, அவன் முதுகில் தள்ளி இழுத்துச் செல்லுங்கள். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾خُذُوهُ</span> <span class=\"quran-arabic-font text-success\">فَاعْتِلُوهُ﴿</span><br />\r\n<br />\r\n(அவனைப் பிடித்து இழுத்துச் செல்லுங்கள்) என்பது அவனைப் பிடித்துத் தள்ளுவதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِلَى</span> <span class=\"quran-arabic-font text-success\">سَوَآءِ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ﴿</span><br />\r\n<br />\r\n(கொழுந்துவிட்டு எரியும் நெருப்பின் நடுவிற்கு.) அதாவது, அதன் மையப்பகுதிக்கு.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">صُبُّواْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">رَأْسِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிறகு அவன் தலைக்கு மேல் கொதிக்கும் நீரின் வேதனையை ஊற்றுங்கள்.) இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هَـذَانِ</span> <span class=\"quran-arabic-font text-success\">خَصْمَانِ</span> <span class=\"quran-arabic-font text-success\">اخْتَصَمُواْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">فَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">قُطِّعَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">ثِيَابٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">نَّارٍ</span> <span class=\"quran-arabic-font text-success\">يُصَبُّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَوْقِ</span> <span class=\"quran-arabic-font text-success\">رُءُوسِهِمُ</span> <span class=\"quran-arabic-font text-success\">الْحَمِيمُ</span> - <span class=\"quran-arabic-font text-success\">يُصْهَرُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بُطُونِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَالْجُلُودُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்களுடைய தலைகளின் மீது கொதிக்கும் நீர் ஊற்றப்படும். அதன் மூலம் அவர்களுடைய வயிறுகளில் உள்ளவையும், தோல்களும் உருக்கப்படும்.) (<a href=\"qurandisp.php?sura=22&ayah=19\" class=\"link\">22:19</a>-20). வானவர் இரும்பாலான வளைந்த தடியால் அவனை அடித்து, அவன் தலையைப் பிளப்பார்; பிறகு அவன் தலை மீது கொதிக்கும் நீரை ஊற்றுவார். அது அவன் உடல் வழியாக இறங்கி, அவன் வயிறு மற்றும் குடல்களை உருக்கி, அவனது குதிகால்கள் வழியாக வெளியேறும்; அல்லாஹ் நம்மை அதிலிருந்து பாதுகாப்பானாக.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذُقْ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இதைச் சுவைப்பாயாக! நிச்சயமாக, நீ (உன்னை) கண்ணியமிக்கவன், பெருந்தன்மையானவன் என்று (நினைத்துக் கொண்டிருந்தாய்).) அதாவது, நரகத்தின் காவலர்கள் அவனிடம் ஏளனமாகவும் கண்டனமாகவும் இவ்வாறு கூறுவார்கள். அத்-தஹ்ஹாக் (ரஹ்) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், நீ கண்ணியமானவனும் அல்ல, பெருந்தன்மையானவனும் அல்ல என்பதுதான்.\"<br />\r\n<br />\r\nமேலும் அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">تَمْتَرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, இதுதான் நீங்கள் சந்தேகித்துக் கொண்டிருந்த விஷயமாகும்!) என்பது அவனது இந்தக் கூற்றைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُدَعُّونَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">نَارِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَعًّا</span> - <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ</span> - <span class=\"quran-arabic-font text-success\">أَفَسِحْرٌ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُبْصِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில் அவர்கள் நரக நெருப்பின் பக்கம் பலவந்தமாகத் தள்ளப்படுவார்கள். இதுதான் நீங்கள் மறுத்துக் கொண்டிருந்த அந்த நெருப்பு. இது சூனியமா? அல்லது நீங்கள் பார்க்கவில்லையா?) (52: 13-15)<br />\r\n<br />","text":"1. மறுமை நாளில் இணைவைப்பவர்களின் நிலையும் அவர்களுக்கான தண்டனையும்\n\r\n\n\r\nதன்னைச் சந்திப்பதை மறுக்கும் நிராகரிப்பாளர்களைத் தான் எவ்வாறு தண்டிப்பான் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّ شَجَرَةَ الزَّقُّومِ - طَعَامُ الْأَثِيمِ ﴿\n\r\n\n\r\n(நிச்சயமாக, ஸக்கூம் மரம் பாவிகளின் உணவாக இருக்கும்.) அதாவது, சொல்லாலும் செயலாலும் பாவம் செய்தவர்கள்; இவர்களே அந்த நிராகரிப்பாளர்கள். இது அபூ ஜஹ்லைக் குறிக்கிறது என்று ஒன்றுக்கும் மேற்பட்ட விரிவுரையாளர்கள் கூறியுள்ளனர். சந்தேகமின்றி, இந்த வசனத்தில் குறிப்பிடப்பட்டவர்களில் அவரும் அடங்குவார்; ஆனால், இது அவரை மட்டும் குறிப்பானது அல்ல. இப்னு ஜரீர் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ அத்-தர்தா (ரழி) அவர்கள் ஒரு மனிதருக்கு ஓதிக் காட்டிக் கொண்டிருந்தார்கள்:\n\r\n\n\r\n﴾إِنَّ شَجَرَةَ الزَّقُّومِ - طَعَامُ الْأَثِيمِ ﴿\n\r\n\n\r\n(நிச்சயமாக, ஸக்கூம் மரம் பாவிகளின் உணவாக இருக்கும்.) அந்த மனிதர், \"(அநாதையின்) உணவு\" என்று ஓதினார். அதற்கு அபூ அத்-தர்தா (ரழி) அவர்கள், \"ஸக்கூம் மரம் தீயவனின் (ஃபாஜிர்) உணவு என்று சொல்\" என்றார்கள். அதாவது, அவனுக்கு அதைத் தவிர வேறு எந்த உணவும் இருக்காது. முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"அதிலிருந்து ஒரு துளி பூமியில் விழுந்தால், அது பூமியில் வாழும் அனைத்து மக்களின் வாழ்வாதாரத்தையும் சீரழித்துவிடும்.\" இது போன்ற ஒரு மர்ஃபூஃ (நபிமொழி) அறிவிப்பு முன்னரே விவரிக்கப்பட்டுள்ளது.\n\r\n\n\r\n﴾كَالْمُهْلِ﴿\n\r\n\n\r\n(கொதிக்கும் எண்ணெயைப் போல,) அதாவது, எண்ணெயின் கசடைப் போல இருக்கும்.\n\r\n\n\r\n﴾كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ - كَغَلْيِ الْحَمِيمِ ﴿\n\r\n\n\r\n(அது வயிறுகளில் கொதிக்கும், சுடுநீர் கொதிப்பதைப் போல.) அதாவது, அதன் அதீத வெப்பம் மற்றும் துர்நாற்றத்தின் காரணமாக அவ்வாறு இருக்கும்.\n\r\n\n\r\n﴾خُذُوهُ﴿\n\r\n\n\r\n(அவனைப் பிடியுங்கள்) என்பது நிராகரிப்பாளரைக் குறிக்கிறது. நரகத்தின் காவலர்களிடம் \"அவனைப் பிடியுங்கள்\" என்று அல்லாஹ் கூறும்போது, அவர்களில் எழுபதாயிரம் பேர் அவனைப் பிடிக்க விரைந்து வருவார்கள் என்று அறிவிக்கப்பட்டுள்ளது.\n\r\n\n\r\n﴾فَاعْتِلُوهُ﴿\n\r\n\n\r\n(இழுத்துச் செல்லுங்கள்) அதாவது, அவனை இழுத்து, அவன் முதுகில் தள்ளி இழுத்துச் செல்லுங்கள். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾خُذُوهُ فَاعْتِلُوهُ﴿\n\r\n\n\r\n(அவனைப் பிடித்து இழுத்துச் செல்லுங்கள்) என்பது அவனைப் பிடித்துத் தள்ளுவதைக் குறிக்கும்.\n\r\n\n\r\n﴾إِلَى سَوَآءِ الْجَحِيمِ﴿\n\r\n\n\r\n(கொழுந்துவிட்டு எரியும் நெருப்பின் நடுவிற்கு.) அதாவது, அதன் மையப்பகுதிக்கு.\n\r\n\n\r\n﴾ثُمَّ صُبُّواْ فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ ﴿\n\r\n\n\r\n(பிறகு அவன் தலைக்கு மேல் கொதிக்கும் நீரின் வேதனையை ஊற்றுங்கள்.) இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾هَـذَانِ خَصْمَانِ اخْتَصَمُواْ فِي رَبِّهِمْ فَالَّذِينَ كَفَرُواْ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ - يُصْهَرُ بِهِ مَا فِي بُطُونِهِمْ وَالْجُلُودُ ﴿\n\r\n\n\r\n(அவர்களுடைய தலைகளின் மீது கொதிக்கும் நீர் ஊற்றப்படும். அதன் மூலம் அவர்களுடைய வயிறுகளில் உள்ளவையும், தோல்களும் உருக்கப்படும்.) (22:19-20). வானவர் இரும்பாலான வளைந்த தடியால் அவனை அடித்து, அவன் தலையைப் பிளப்பார்; பிறகு அவன் தலை மீது கொதிக்கும் நீரை ஊற்றுவார். அது அவன் உடல் வழியாக இறங்கி, அவன் வயிறு மற்றும் குடல்களை உருக்கி, அவனது குதிகால்கள் வழியாக வெளியேறும்; அல்லாஹ் நம்மை அதிலிருந்து பாதுகாப்பானாக.\n\r\n\n\r\n﴾ذُقْ إِنَّكَ أَنتَ الْعَزِيزُ الْكَرِيمُ ﴿\n\r\n\n\r\n(இதைச் சுவைப்பாயாக! நிச்சயமாக, நீ (உன்னை) கண்ணியமிக்கவன், பெருந்தன்மையானவன் என்று (நினைத்துக் கொண்டிருந்தாய்).) அதாவது, நரகத்தின் காவலர்கள் அவனிடம் ஏளனமாகவும் கண்டனமாகவும் இவ்வாறு கூறுவார்கள். அத்-தஹ்ஹாக் (ரஹ்) அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"இதன் பொருள், நீ கண்ணியமானவனும் அல்ல, பெருந்தன்மையானவனும் அல்ல என்பதுதான்.\"\n\r\n\n\r\nமேலும் அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n﴾إِنَّ هَـذَا مَا كُنتُمْ بِهِ تَمْتَرُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக, இதுதான் நீங்கள் சந்தேகித்துக் கொண்டிருந்த விஷயமாகும்!) என்பது அவனது இந்தக் கூற்றைப் போன்றது:\n\r\n\n\r\n﴾يَوْمَ يُدَعُّونَ إِلَى نَارِ جَهَنَّمَ دَعًّا - هَـذِهِ النَّارُ الَّتِى كُنتُم بِهَا تُكَذِّبُونَ - أَفَسِحْرٌ هَـذَا أَمْ أَنتُمْ لاَ تُبْصِرُونَ ﴿\n\r\n\n\r\n(அந்நாளில் அவர்கள் நரக நெருப்பின் பக்கம் பலவந்தமாகத் தள்ளப்படுவார்கள். இதுதான் நீங்கள் மறுத்துக் கொண்டிருந்த அந்த நெருப்பு. இது சூனியமா? அல்லது நீங்கள் பார்க்கவில்லையா?) (52: 13-15)"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"56":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=44&ayah=59\" class=\"link\">44:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 44:59 ஐ பார்க்கவும்"},"59":{"html":"<strong>தக்வா (இறையச்சம்) உடையவர்களின் நிலையும், அவர்கள் சொர்க்கத்தில் அனுபவிக்கும் இன்பங்களும்</strong><br />\r\n<br />\r\nநரகவாசிகளின் நிலையை அல்லாஹ் விவரிக்கும்போது, அதைத் தொடர்ந்து பாக்கியம் பெற்றவர்களின் வாழ்க்கையைப் பற்றியும் அவன் விவரிக்கிறான். இதன் காரணமாகவே குர்ஆன் 'அல்-மஸானீ' (அடிக்கடித் திரும்பத் திரும்பக் கூறப்படுவது) என்று அழைக்கப்படுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span><br />\r\n(நிச்சயமாக, தக்வா உடையவர்கள்,) அதாவது, இவ்வுலகில் அல்லாஹ்வுக்கு அஞ்சி, அவனுக்குக் கீழ்ப்படிந்து நடந்துகொள்பவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">مَقَامٍ</span> <span class=\"quran-arabic-font text-success\">أَمِينٍ</span><br />\r\n(பாதுகாப்பான இடத்தில் இருப்பார்கள்.) இதன் பொருள், மறுமையில், அதாவது சொர்க்கத்தில், மரணத்திலிருந்தும், அங்கிருந்து வெளியேற்றப்படுவோம் என்ற பயத்திலிருந்தும் அவர்கள் பாதுகாப்பாக இருப்பார்கள். மேலும் கவலை, துக்கம், அச்சம், சோர்வு, ஷைத்தான் மற்றும் அவனது சூழ்ச்சிகள் மற்றும் அனைத்து விதமான துன்பங்கள் மற்றும் பேரழிவுகளிலிருந்தும் அவர்கள் பாதுகாப்பாக இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَعُيُونٍ</span><br />\r\n(சோலைகளிலும் நீரூற்றுகளிலும் இருப்பார்கள்). இது ஸக்கூம் மரமும் கொதிக்கும் நீரும் கொண்ட நரகவாசிகளின் நிலைக்கு நேர்மாறானதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَلْبَسُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سُندُسٍ</span><br />\r\n(அவர்கள் 'சுந்துஸ்' அணிந்திருப்பார்கள்) இதன் பொருள், மிக மெல்லிய பட்டுத் துணியால் ஆன சட்டைகள் மற்றும் அதுபோன்ற ஆடைகள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِسْتَبْرَقٍ</span><br />\r\n(மற்றும் 'இஸ்தப்ரக்') இதன் பொருள், பளபளப்பான நூல்களால் நெய்யப்பட்ட கனமான பட்டு ஆடை; இது சாதாரண ஆடைகளுக்கு மேல் அணியப்படும் ஒரு மேலாடையைப் போன்றது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُتَقَابِلِينَ</span><br />\r\n(ஒருவரையொருவர் முன்னோக்கியவர்களாக) இதன் பொருள், அவர்கள் சிம்மாசனங்களில் அமர்ந்திருப்பார்கள்; அங்கு எவரும் மற்றவருக்குப் புறமுதுகு காட்டி அமர மாட்டார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَزَوَّجْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِحُورٍ</span> <span class=\"quran-arabic-font text-success\">عِينٍ</span><br />\r\n(இவ்வாறே (அவர்களுக்கு அமையும்). மேலும், அகன்ற அழகான கண்களைக் கொண்ட 'ஹூருல் ஈன்'களுடன் நாம் அவர்களுக்குத் திருமணம் செய்து வைப்போம்.) இது அவர்களுக்கு வழங்கப்பட்ட அழகான மனைவியருடன் கூடுதலாக வழங்கப்படவுள்ள ஒரு பரிசாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَطْمِثْهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِنسٌ</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">جَآنٌّ</span><br />\r\n(அவர்களுக்கு முன்னால் எந்த மனிதனோ அல்லது ஜின்னோ அவர்களைத் தீண்டியதில்லை (தாம்பத்திய உறவு கொண்டதில்லை).) (<a href=\"qurandisp.php?sura=55&ayah=56\" class=\"link\">55:56</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَأَنَّهُنَّ</span> <span class=\"quran-arabic-font text-success\">الْيَاقُوتُ</span> <span class=\"quran-arabic-font text-success\">وَالْمَرْجَانُ</span><br />\r\n((அழகில்) அவர்கள் யாக்கூத் (மாணிக்கம்) மற்றும் மர்ஜான் (பவளம்) போன்றவர்கள்.) (<a href=\"qurandisp.php?sura=55&ayah=58\" class=\"link\">55:58</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">جَزَآءُ</span> <span class=\"quran-arabic-font text-success\">الْإِحْسَانِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْإِحْسَانُ</span><br />\r\n(நன்மைக்கு நன்மையைத் தவிர வேறு ஏதேனும் கூலி உண்டா?) (<a href=\"qurandisp.php?sura=55&ayah=60\" class=\"link\">55:60</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">فَاكِهَةٍ</span> <span class=\"quran-arabic-font text-success\">ءَامِنِينَ</span><br />\r\n(அவர்கள் அங்கு எல்லா வகையான கனிகளையும் அமைதியுடனும் பாதுகாப்புடனும் வேண்டுவார்கள்;) இதன் பொருள், அவர்கள் கேட்கும் கனிகள் அனைத்தும் அவர்களுக்குக் கொண்டு வரப்படும். மேலும் அக் கனிகளின் வரத்து ஒருபோதும் முடிவடையாது அல்லது தடைபடாது என்ற நிம்மதி அவர்களுக்கு இருக்கும். அவர்கள் விரும்பும் போதெல்லாம் அக் கனிகள் அவர்களுக்கு வழங்கப்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَذُوقُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَةَ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span><br />\r\n(அங்கு அவர்கள் தங்களின் முதல் மரணத்தைத் தவிர வேறு எந்த மரணத்தையும் சுவைக்க மாட்டார்கள்.) இது அந்த மறுப்பை (மரணமே இல்லை என்பதை) வலியுறுத்துவதற்காகக் கூறப்படும் ஒரு விதிவிலக்காகும். அதாவது அங்கு அவர்கள் ஒருபோதும் மரணத்தைச் சுவைக்க மாட்டார்கள். இரண்டு ஸஹீஹ்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُؤْتَى</span> <span class=\"quran-arabic-font text-success\">بِالْمَوْتِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُورَةِ</span> <span class=\"quran-arabic-font text-success\">كَبْشٍ</span> <span class=\"quran-arabic-font text-success\">أَمْلَحَ</span> <span class=\"quran-arabic-font text-success\">فَيُوقَفُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّارِ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُذْبَحُ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">خُلُودٌ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">مَوْتَ،</span> <span class=\"quran-arabic-font text-success\">وَيَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">خُلُودٌ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">مَوْت</span>»<br />\r\n(மரணமானது ஒரு அழகான ஆட்டுக்கடாவின் உருவத்தில் கொண்டு வரப்பட்டு, சொர்க்கத்திற்கும் நரகத்திற்கும் இடையே நிறுத்தப்படும். பின்னர் அது அறுக்கப்படும். அதன் பிறகு, \"சொர்க்கவாசிகளே! இது நிலையானது, இனி மரணமே இல்லை. நரகவாசிகளே! இது நிலையானது, இனி மரணமே இல்லை\" என்று கூறப்படும்.) இந்த ஹதீஸ் சூரா மர்யமின் தஃப்சீரில் ஏற்கனவே மேற்கோள் காட்டப்பட்டுள்ளது. அப்துர் ரஸ்ஸாக் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஸயீத் (ரழி) மற்றும் அபூ ஹுரைரா (ரழி) ஆகியோர் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">لِأَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span>: <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَصِحُّوا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَسْقَمُوا</span> <span class=\"quran-arabic-font text-success\">أَبَدًا،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَعِيشُوا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَمُوتُوا</span> <span class=\"quran-arabic-font text-success\">أَبَدًا،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَنْعَمُوا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَبْأَسُوا</span> <span class=\"quran-arabic-font text-success\">أَبَدًا،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَشِبُّوا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَهْرَمُوا</span> <span class=\"quran-arabic-font text-success\">أَبَدًا</span>»<br />\r\n(சொர்க்கவாசிகளிடம் கூறப்படும்: \"நிச்சயமாக நீங்கள் இனி எப்போதும் ஆரோக்கியமாக இருப்பீர்கள், ஒருபோதும் நோய்வாய்ப்பட மாட்டீர்கள்; நீங்கள் வாழ்வீர்கள், ஒருபோதும் மரணிக்க மாட்டீர்கள்; நீங்கள் இன்பமாக வாழ்வீர்கள், ஒருபோதும் துன்பப்பட மாட்டீர்கள்; நீங்கள் எப்போதும் இளைஞர்களாகவே இருப்பீர்கள், ஒருபோதும் முதுமையடைய மாட்டீர்கள்.\")\" இதை முஸ்லிம் பதிவு செய்துள்ளார். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்துள்ளார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّقَى</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ،</span> <span class=\"quran-arabic-font text-success\">يَنْعَمُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَبْأَسُ،</span> <span class=\"quran-arabic-font text-success\">وَيَحْيَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَبْلَى</span> <span class=\"quran-arabic-font text-success\">ثِيَابُهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَفْنَى</span> <span class=\"quran-arabic-font text-success\">شَبَابُه</span>»<br />\r\n(எவர் அல்லாஹ்விடம் தக்வா கொண்டுள்ளாரோ அவர் சொர்க்கத்தில் நுழைவார். அங்கு இன்பமாக வாழ்வார், ஒருபோதும் துன்புற மாட்டார். அவர் அங்கேயே வாழ்வார், மரணிக்கவே மாட்டார். அவரது ஆடைகள் ஒருபோதும் பழையாகாது; அவரது இளமை ஒருபோதும் அழியாது.)\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَوَقَاهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span><br />\r\n(மேலும் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து அவன் அவர்களைக் காப்பாற்றினான்.) இதன் பொருள், இந்த மாபெரும் மற்றும் நிலையான அருட்கொடைகளுடன், நரகத்தின் ஆழத்தில் உள்ள மிகக் கொடிய வேதனையிலிருந்தும் அவன் அவர்களைக் காப்பாற்றினான். இதன் மூலம் அவர்கள் எதை நாடினார்களோ அதை அடைந்தனர், எதை அஞ்சினார்களோ அதிலிருந்து தப்பித்துக்கொண்டனர். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَضْلاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْفَوْزُ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمُ</span><br />\r\n((இது) உமது இறைவனிடமிருந்துள்ள அருட்கொடையாகும்! அதுவே மகத்தான வெற்றியாகும்!) இதன் பொருள், அது அவர்கள் மீதான அவனது அருளாலும் கருணையாலும் கிட்டியதாகும். இரண்டு ஸஹீஹ்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اعْمَلُوا</span> <span class=\"quran-arabic-font text-success\">وَسَدِّدُوا</span> <span class=\"quran-arabic-font text-success\">وَقَارِبُوا،</span> <span class=\"quran-arabic-font text-success\">وَاعْلَمُوا</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدًا</span> <span class=\"quran-arabic-font text-success\">لَنْ</span> <span class=\"quran-arabic-font text-success\">يُدْخِلَهُ</span> <span class=\"quran-arabic-font text-success\">عَمَلُهُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n(நற்கருமங்களைச் செய்யுங்கள், நேர்மையாக இருங்கள், நன்மையை நெருங்குங்கள். மேலும் அறிந்து கொள்ளுங்கள், எவருமே தனது செயல்களினால் மட்டும் சொர்க்கத்தில் நுழைய முடியாது.) அவர்கள், \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" என்று கேட்டார்கள். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">أَنَا،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَتَغَمَّدَنِيَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِرَحْمَةٍ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">وَفَضْل</span>»<br />\r\n(நானும்தான், அல்லாஹ் தனது அருளாலும் கருணையாலும் என்னைச் சூழ்ந்து கொண்டாலன்றி.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِلِسَانِكَ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُونَ</span><br />\r\n(நிச்சயமாக, அவர்கள் நினைவுகூரும் பொருட்டு, இதை உமது மொழியில் நாம் எளிதாக்கினோம்.) இதன் பொருள், 'நாம் இறக்கியருளிய இந்த குர்ஆனை, எல்லா மொழிகளிலும் மிகச் சிறந்த, தெளிவான மற்றும் அழகான உமது மொழியில் நாம் எளிமையாகவும் தெளிவாகவும் ஆக்கியுள்ளோம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَتَذَكَّرُونَ</span><br />\r\n(அவர்கள் நினைவுகூரும் பொருட்டு.) இதன் பொருள், அவர்கள் புரிந்து கொள்ளவும் அறிந்து கொள்ளவும் வேண்டும் என்பதற்காக. இது மிகவும் தெளிவாகவும் விளக்கமாகவும் இருந்தபோதிலும், இன்னமும் இதைப் பொய்ப்பிக்கின்ற மற்றும் பிடிவாதமாக எதிர்க்கின்ற மக்கள் இருக்கத்தான் செய்கிறார்கள். அல்லாஹ் தனது தூதர் (ஸல்) அவர்களுக்கு ஆறுதல் கூறி, அவருக்கு வெற்றியளிப்பதாக வாக்களிக்கிறான்; மேலும் அவரை நிராகரிப்பவர்கள் அழிக்கப்படுவார்கள் என எச்சரிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْتَقِبْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّرْتَقِبُونَ</span><br />\r\n(ஆகவே நீர் காத்திருப்பீராக; நிச்சயமாக அவர்களும் காத்திருக்கிறார்கள்.) இதன் பொருள், 'இவ்வுலகிலும் மறுமையிலும் யார் வெற்றி பெறப்போகிறார்கள், யாருடைய சொல் மேலோங்கப் போகிறது என்பதை அவர்கள் அறிந்து கொள்வார்கள். முஹம்மதே (ஸல்)! வெற்றி உமக்கும், நபிமார்கள் மற்றும் தூதர்களில் உள்ள உமது சகோதரர்களுக்கும், உம்மைப் பின்தொடர்ந்த முஃமின்களுக்கும் (நம்பிக்கையாளர்களுக்கும்) தான்' என்று அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَتَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَأَغْلِبَنَّ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">وَرُسُلِى</span><br />\r\n(அல்லாஹ் விதித்துள்ளான்: 'நிச்சயமாக நானும் எனது தூதர்களுமே வெற்றி பெறுவோம்.') (<a href=\"qurandisp.php?sura=58&ayah=21\" class=\"link\">58:21</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَنصُرُ</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَقُومُ</span> <span class=\"quran-arabic-font text-success\">الْأَشْهَادُ</span> - <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">مَعْذِرَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّعْنَةُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">سُوءُ</span> <span class=\"quran-arabic-font text-success\">الدَّارِ</span><br />\r\n(நிச்சயமாக நாம் நமது தூதர்களுக்கும், ஈமான் கொண்டவர்களுக்கும் இவ்வுலக வாழ்விலும், சாட்சிகள் நிற்கும் (மறுமை) நாளிலும் உதவி செய்வோம். -- அந்த நாளில் அநியாயக்காரர்களுக்கு அவர்களின் சாக்குப்போக்குகள் யாதொரு பயனும் அளிக்காது. அவர்களுக்குச் சாபமுண்டு; அவர்களுக்குத் தீய இருப்பிடமும் உண்டு.) (<a href=\"qurandisp.php?sura=40&ayah=51\" class=\"link\">40:51</a>-52)<br />\r\n<br />\r\nஇத்துடன் சூரா அத்-துகானின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது. அவனிடமே அனைத்து வலிமையும் பாதுகாப்பும் உள்ளன.<br />\r\n<br />","text":"தக்வா (இறையச்சம்) உடையவர்களின் நிலையும், அவர்கள் சொர்க்கத்தில் அனுபவிக்கும் இன்பங்களும்\n\r\n\n\r\nநரகவாசிகளின் நிலையை அல்லாஹ் விவரிக்கும்போது, அதைத் தொடர்ந்து பாக்கியம் பெற்றவர்களின் வாழ்க்கையைப் பற்றியும் அவன் விவரிக்கிறான். இதன் காரணமாகவே குர்ஆன் 'அல்-மஸானீ' (அடிக்கடித் திரும்பத் திரும்பக் கூறப்படுவது) என்று அழைக்கப்படுகிறது.\n\r\n\n\r\nإِنَّ الْمُتَّقِينَ\n\r\n(நிச்சயமாக, தக்வா உடையவர்கள்,) அதாவது, இவ்வுலகில் அல்லாஹ்வுக்கு அஞ்சி, அவனுக்குக் கீழ்ப்படிந்து நடந்துகொள்பவர்கள்,\n\r\n\n\r\nفِى مَقَامٍ أَمِينٍ\n\r\n(பாதுகாப்பான இடத்தில் இருப்பார்கள்.) இதன் பொருள், மறுமையில், அதாவது சொர்க்கத்தில், மரணத்திலிருந்தும், அங்கிருந்து வெளியேற்றப்படுவோம் என்ற பயத்திலிருந்தும் அவர்கள் பாதுகாப்பாக இருப்பார்கள். மேலும் கவலை, துக்கம், அச்சம், சோர்வு, ஷைத்தான் மற்றும் அவனது சூழ்ச்சிகள் மற்றும் அனைத்து விதமான துன்பங்கள் மற்றும் பேரழிவுகளிலிருந்தும் அவர்கள் பாதுகாப்பாக இருப்பார்கள்.\n\r\n\n\r\nفِى جَنَّاتٍ وَعُيُونٍ\n\r\n(சோலைகளிலும் நீரூற்றுகளிலும் இருப்பார்கள்). இது ஸக்கூம் மரமும் கொதிக்கும் நீரும் கொண்ட நரகவாசிகளின் நிலைக்கு நேர்மாறானதாகும்.\n\r\n\n\r\nيَلْبَسُونَ مِن سُندُسٍ\n\r\n(அவர்கள் 'சுந்துஸ்' அணிந்திருப்பார்கள்) இதன் பொருள், மிக மெல்லிய பட்டுத் துணியால் ஆன சட்டைகள் மற்றும் அதுபோன்ற ஆடைகள்.\n\r\n\n\r\nوَإِسْتَبْرَقٍ\n\r\n(மற்றும் 'இஸ்தப்ரக்') இதன் பொருள், பளபளப்பான நூல்களால் நெய்யப்பட்ட கனமான பட்டு ஆடை; இது சாதாரண ஆடைகளுக்கு மேல் அணியப்படும் ஒரு மேலாடையைப் போன்றது.\n\r\n\n\r\nمُتَقَابِلِينَ\n\r\n(ஒருவரையொருவர் முன்னோக்கியவர்களாக) இதன் பொருள், அவர்கள் சிம்மாசனங்களில் அமர்ந்திருப்பார்கள்; அங்கு எவரும் மற்றவருக்குப் புறமுதுகு காட்டி அமர மாட்டார்கள்.\n\r\n\n\r\nكَذَلِكَ وَزَوَّجْنَاهُم بِحُورٍ عِينٍ\n\r\n(இவ்வாறே (அவர்களுக்கு அமையும்). மேலும், அகன்ற அழகான கண்களைக் கொண்ட 'ஹூருல் ஈன்'களுடன் நாம் அவர்களுக்குத் திருமணம் செய்து வைப்போம்.) இது அவர்களுக்கு வழங்கப்பட்ட அழகான மனைவியருடன் கூடுதலாக வழங்கப்படவுள்ள ஒரு பரிசாகும்.\n\r\n\n\r\nلَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلاَ جَآنٌّ\n\r\n(அவர்களுக்கு முன்னால் எந்த மனிதனோ அல்லது ஜின்னோ அவர்களைத் தீண்டியதில்லை (தாம்பத்திய உறவு கொண்டதில்லை).) (55:56)\n\r\n\n\r\nكَأَنَّهُنَّ الْيَاقُوتُ وَالْمَرْجَانُ\n\r\n((அழகில்) அவர்கள் யாக்கூத் (மாணிக்கம்) மற்றும் மர்ஜான் (பவளம்) போன்றவர்கள்.) (55:58)\n\r\n\n\r\nهَلْ جَزَآءُ الْإِحْسَانِ إِلاَّ الْإِحْسَانُ\n\r\n(நன்மைக்கு நன்மையைத் தவிர வேறு ஏதேனும் கூலி உண்டா?) (55:60)\n\r\n\n\r\nيَدْعُونَ فِيهَا بِكُلِّ فَاكِهَةٍ ءَامِنِينَ\n\r\n(அவர்கள் அங்கு எல்லா வகையான கனிகளையும் அமைதியுடனும் பாதுகாப்புடனும் வேண்டுவார்கள்;) இதன் பொருள், அவர்கள் கேட்கும் கனிகள் அனைத்தும் அவர்களுக்குக் கொண்டு வரப்படும். மேலும் அக் கனிகளின் வரத்து ஒருபோதும் முடிவடையாது அல்லது தடைபடாது என்ற நிம்மதி அவர்களுக்கு இருக்கும். அவர்கள் விரும்பும் போதெல்லாம் அக் கனிகள் அவர்களுக்கு வழங்கப்படும்.\n\r\n\n\r\nلاَ يَذُوقُونَ فِيهَا الْمَوْتَ إِلاَّ الْمَوْتَةَ الْأُولَى\n\r\n(அங்கு அவர்கள் தங்களின் முதல் மரணத்தைத் தவிர வேறு எந்த மரணத்தையும் சுவைக்க மாட்டார்கள்.) இது அந்த மறுப்பை (மரணமே இல்லை என்பதை) வலியுறுத்துவதற்காகக் கூறப்படும் ஒரு விதிவிலக்காகும். அதாவது அங்கு அவர்கள் ஒருபோதும் மரணத்தைச் சுவைக்க மாட்டார்கள். இரண்டு ஸஹீஹ்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கப்பட்டுள்ளது:\n\r\n\n\r\n«يُؤْتَى بِالْمَوْتِ فِي صُورَةِ كَبْشٍ أَمْلَحَ فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُذْبَحُ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ فَلَا مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ فَلَا مَوْت»\n\r\n(மரணமானது ஒரு அழகான ஆட்டுக்கடாவின் உருவத்தில் கொண்டு வரப்பட்டு, சொர்க்கத்திற்கும் நரகத்திற்கும் இடையே நிறுத்தப்படும். பின்னர் அது அறுக்கப்படும். அதன் பிறகு, \"சொர்க்கவாசிகளே! இது நிலையானது, இனி மரணமே இல்லை. நரகவாசிகளே! இது நிலையானது, இனி மரணமே இல்லை\" என்று கூறப்படும்.) இந்த ஹதீஸ் சூரா மர்யமின் தஃப்சீரில் ஏற்கனவே மேற்கோள் காட்டப்பட்டுள்ளது. அப்துர் ரஸ்ஸாக் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஸயீத் (ரழி) மற்றும் அபூ ஹுரைரா (ரழி) ஆகியோர் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يُقَالُ لِأَهْلِ الْجَنَّةِ: إِنَّ لَكُمْ أَنْ تَصِحُّوا فَلَا تَسْقَمُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَعِيشُوا فَلَا تَمُوتُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَنْعَمُوا فَلَا تَبْأَسُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَشِبُّوا فَلَا تَهْرَمُوا أَبَدًا»\n\r\n(சொர்க்கவாசிகளிடம் கூறப்படும்: \"நிச்சயமாக நீங்கள் இனி எப்போதும் ஆரோக்கியமாக இருப்பீர்கள், ஒருபோதும் நோய்வாய்ப்பட மாட்டீர்கள்; நீங்கள் வாழ்வீர்கள், ஒருபோதும் மரணிக்க மாட்டீர்கள்; நீங்கள் இன்பமாக வாழ்வீர்கள், ஒருபோதும் துன்பப்பட மாட்டீர்கள்; நீங்கள் எப்போதும் இளைஞர்களாகவே இருப்பீர்கள், ஒருபோதும் முதுமையடைய மாட்டீர்கள்.\")\" இதை முஸ்லிம் பதிவு செய்துள்ளார். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்துள்ளார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنِ اتَّقَى اللهَ دَخَلَ الْجَنَّةَ، يَنْعَمُ فِيهَا وَلَا يَبْأَسُ، وَيَحْيَا فِيهَا فَلَا يَمُوتُ، لَا تَبْلَى ثِيَابُهُ، وَلَا يَفْنَى شَبَابُه»\n\r\n(எவர் அல்லாஹ்விடம் தக்வா கொண்டுள்ளாரோ அவர் சொர்க்கத்தில் நுழைவார். அங்கு இன்பமாக வாழ்வார், ஒருபோதும் துன்புற மாட்டார். அவர் அங்கேயே வாழ்வார், மரணிக்கவே மாட்டார். அவரது ஆடைகள் ஒருபோதும் பழையாகாது; அவரது இளமை ஒருபோதும் அழியாது.)\"\n\r\n\n\r\nوَوَقَاهُمْ عَذَابَ الْجَحِيمِ\n\r\n(மேலும் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து அவன் அவர்களைக் காப்பாற்றினான்.) இதன் பொருள், இந்த மாபெரும் மற்றும் நிலையான அருட்கொடைகளுடன், நரகத்தின் ஆழத்தில் உள்ள மிகக் கொடிய வேதனையிலிருந்தும் அவன் அவர்களைக் காப்பாற்றினான். இதன் மூலம் அவர்கள் எதை நாடினார்களோ அதை அடைந்தனர், எதை அஞ்சினார்களோ அதிலிருந்து தப்பித்துக்கொண்டனர். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَضْلاً مِّن رَّبِّكَ ذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ\n\r\n((இது) உமது இறைவனிடமிருந்துள்ள அருட்கொடையாகும்! அதுவே மகத்தான வெற்றியாகும்!) இதன் பொருள், அது அவர்கள் மீதான அவனது அருளாலும் கருணையாலும் கிட்டியதாகும். இரண்டு ஸஹீஹ்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கப்பட்டுள்ளது:\n\r\n\n\r\n«اعْمَلُوا وَسَدِّدُوا وَقَارِبُوا، وَاعْلَمُوا أَنَّ أَحَدًا لَنْ يُدْخِلَهُ عَمَلُهُ الْجَنَّة»\n\r\n(நற்கருமங்களைச் செய்யுங்கள், நேர்மையாக இருங்கள், நன்மையை நெருங்குங்கள். மேலும் அறிந்து கொள்ளுங்கள், எவருமே தனது செயல்களினால் மட்டும் சொர்க்கத்தில் நுழைய முடியாது.) அவர்கள், \"அல்லாஹ்வின் தூதரே! நீங்களுமா?\" என்று கேட்டார்கள். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِيَ اللهُ بِرَحْمَةٍ مِنْهُ وَفَضْل»\n\r\n(நானும்தான், அல்லாஹ் தனது அருளாலும் கருணையாலும் என்னைச் சூழ்ந்து கொண்டாலன்றி.)\n\r\n\n\r\nفَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ\n\r\n(நிச்சயமாக, அவர்கள் நினைவுகூரும் பொருட்டு, இதை உமது மொழியில் நாம் எளிதாக்கினோம்.) இதன் பொருள், 'நாம் இறக்கியருளிய இந்த குர்ஆனை, எல்லா மொழிகளிலும் மிகச் சிறந்த, தெளிவான மற்றும் அழகான உமது மொழியில் நாம் எளிமையாகவும் தெளிவாகவும் ஆக்கியுள்ளோம்.'\n\r\n\n\r\nلَعَلَّهُمْ يَتَذَكَّرُونَ\n\r\n(அவர்கள் நினைவுகூரும் பொருட்டு.) இதன் பொருள், அவர்கள் புரிந்து கொள்ளவும் அறிந்து கொள்ளவும் வேண்டும் என்பதற்காக. இது மிகவும் தெளிவாகவும் விளக்கமாகவும் இருந்தபோதிலும், இன்னமும் இதைப் பொய்ப்பிக்கின்ற மற்றும் பிடிவாதமாக எதிர்க்கின்ற மக்கள் இருக்கத்தான் செய்கிறார்கள். அல்லாஹ் தனது தூதர் (ஸல்) அவர்களுக்கு ஆறுதல் கூறி, அவருக்கு வெற்றியளிப்பதாக வாக்களிக்கிறான்; மேலும் அவரை நிராகரிப்பவர்கள் அழிக்கப்படுவார்கள் என எச்சரிக்கிறான்.\n\r\n\n\r\nفَارْتَقِبْ إِنَّهُمْ مُّرْتَقِبُونَ\n\r\n(ஆகவே நீர் காத்திருப்பீராக; நிச்சயமாக அவர்களும் காத்திருக்கிறார்கள்.) இதன் பொருள், 'இவ்வுலகிலும் மறுமையிலும் யார் வெற்றி பெறப்போகிறார்கள், யாருடைய சொல் மேலோங்கப் போகிறது என்பதை அவர்கள் அறிந்து கொள்வார்கள். முஹம்மதே (ஸல்)! வெற்றி உமக்கும், நபிமார்கள் மற்றும் தூதர்களில் உள்ள உமது சகோதரர்களுக்கும், உம்மைப் பின்தொடர்ந்த முஃமின்களுக்கும் (நம்பிக்கையாளர்களுக்கும்) தான்' என்று அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nكَتَبَ اللَّهُ لَأَغْلِبَنَّ أَنَاْ وَرُسُلِى\n\r\n(அல்லாஹ் விதித்துள்ளான்: 'நிச்சயமாக நானும் எனது தூதர்களுமே வெற்றி பெறுவோம்.') (58:21)\n\r\n\n\r\nإِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ ءَامَنُواْ فِى الْحَيَوةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَادُ - يَوْمَ لاَ يَنفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ\n\r\n(நிச்சயமாக நாம் நமது தூதர்களுக்கும், ஈமான் கொண்டவர்களுக்கும் இவ்வுலக வாழ்விலும், சாட்சிகள் நிற்கும் (மறுமை) நாளிலும் உதவி செய்வோம். -- அந்த நாளில் அநியாயக்காரர்களுக்கு அவர்களின் சாக்குப்போக்குகள் யாதொரு பயனும் அளிக்காது. அவர்களுக்குச் சாபமுண்டு; அவர்களுக்குத் தீய இருப்பிடமும் உண்டு.) (40:51-52)\n\r\n\n\r\nஇத்துடன் சூரா அத்-துகானின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது. அவனிடமே அனைத்து வலிமையும் பாதுகாப்பும் உள்ளன."}}};})(self);
